   152→	Files     []string
   153→}
   154→
   155→// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
   156→// Returns pairs in chronological order (oldest first).
   157→// Each pair contains the user's prompt, assistant's text response, and files modified.
   158→func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
   159→	var pairs []PromptResponsePair
   160→
   161→	// Find all user prompts (messages with string content, not tool results)
   162→	var userIndices []int
   163→	for i, line := range transcript {
   164→		if line.Type == transcriptTypeUser {
   165→			var msg userMessage
   166→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   167→				continue
   168→			}
   169→			// Only count messages with string content (real user prompts)
   170→			if _, ok := msg.Content.(string); ok {
   171→				userIndices = append(userIndices, i)
   172→			} else if arr, ok := msg.Content.([]interface{}); ok {
   173→				// Check if array has text blocks (also a real user prompt)
   174→				for _, item := range arr {
   175→					if m, ok := item.(map[string]interface{}); ok {
   176→						if m["type"] == contentTypeText {
   177→							userIndices = append(userIndices, i)
   178→							break
   179→						}
   180→					}
   181→				}
   182→			}
   183→		}
   184→	}
   185→
   186→	// For each user prompt, extract the prompt text, following assistant response, and files
   187→	for idx, userIdx := range userIndices {
   188→		// Determine the range for this prompt's conversation
   189→		endIdx := len(transcript)
   190→		if idx < len(userIndices)-1 {
   191→			endIdx = userIndices[idx+1]
   192→		}
   193→
   194→		// Extract prompt text
   195→		prompt := extractUserPromptAt(transcript, userIdx)
   196→		if prompt == "" {
   197→			continue
   198→		}
   199→
   200→		// Extract assistant responses and files from this range
   201→		slice := transcript[userIdx:endIdx]
   202→		responses := extractAssistantResponses(slice)
   203→		files := extractModifiedFiles(slice)
   204→
   205→		pairs = append(pairs, PromptResponsePair{
   206→			Prompt:    prompt,
   207→			Responses: responses,
   208→			Files:     files,
   209→		})
   210→	}
   211→
   212→	return pairs
   213→}
   214→
   215→// extractUserPromptAt extracts the user prompt at the given index.
   216→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   217→func extractUserPromptAt(transcript []transcriptLine, idx int) string {
   218→	if idx >= len(transcript) || transcript[idx].Type != transcriptTypeUser {
   219→		return ""
   220→	}
   221→
   222→	var msg userMessage
   223→	if err := json.Unmarshal(transcript[idx].Message, &msg); err != nil {
   224→		return ""
   225→	}
   226→
   227→	// Handle string content
   228→	if str, ok := msg.Content.(string); ok {
   229→		return textutil.StripIDEContextTags(str)
   230→	}
   231→
   232→	// Handle array content (only if it contains text blocks)
   233→	if arr, ok := msg.Content.([]interface{}); ok {
   234→		var texts []string
   235→		for _, item := range arr {
   236→			if m, ok := item.(map[string]interface{}); ok {
   237→				if m["type"] == contentTypeText {
   238→					if text, ok := m["text"].(string); ok {
   239→						texts = append(texts, text)
   240→					}
   241→				}
   242→			}
   243→		}
   244→		if len(texts) > 0 {
   245→			return textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   246→		}
   247→	}
   248→
   249→	return ""
   250→}
   251→
   252→// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
   253→// A single prompt can trigger multiple assistant responses interspersed with tool calls.
   254→func extractAssistantResponses(transcript []transcriptLine) []string {
   255→	var texts []string
   256→	for _, line := range transcript {
   257→		if line.Type == transcriptTypeAssistant {
   258→			var msg assistantMessage
   259→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   260→				continue
   261→			}
   262→
   263→			for _, block := range msg.Content {
   264→				if block.Type == contentTypeText && block.Text != "" {
   265→					texts = append(texts, block.Text)
   266→				}
   267→			}
   268→		}
   269→	}
   270→	return texts
   271→}
   272→
   273→// extractUserPrompts extracts all user messages from the transcript in order.
   274→// Only considers messages with string content (not tool results).
   275→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
   276→func extractUserPrompts(transcript []transcriptLine) []string {
   277→	var prompts []string
   278→	for i := range transcript {
   279→		if transcript[i].Type != transcriptTypeUser {
   280→			continue
   281→		}
   282→		var msg userMessage
   283→		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   284→			continue
   285→		}
   286→
   287→		// Handle string content
   288→		if str, ok := msg.Content.(string); ok {
   289→			prompts = append(prompts, textutil.StripIDEContextTags(str))
   290→			continue
   291→		}
   292→
   293→		// Handle array content (only if it contains text blocks)
   294→		if arr, ok := msg.Content.([]interface{}); ok {
   295→			var texts []string
   296→			for _, item := range arr {
   297→				if m, ok := item.(map[string]interface{}); ok {
   298→					if m["type"] == contentTypeText {
   299→						if text, ok := m["text"].(string); ok {
   300→							texts = append(texts, text)
   301→						}
   302→					}
   303→				}
   304→			}
   305→			if len(texts) > 0 {
   306→				prompts = append(prompts, textutil.StripIDEContextTags(strings.Join(texts, "\n\n")))
   307→			}
   308→		}
   309→	}
   310→	return prompts
   311→}
   312→
   313→// extractLastUserPrompt extracts the last user message from the transcript.
   314→// Only considers messages with string content (not tool results).
   315→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   316→func extractLastUserPrompt(transcript []transcriptLine) string {
   317→	prompts := extractUserPrompts(transcript)
   318→	if len(prompts) == 0 {
   319→		return ""
   320→	}
   321→	return prompts[len(prompts)-1]
   322→}
   323→
   324→// extractLastAssistantMessage extracts the last text message from the assistant
   325→func extractLastAssistantMessage(transcript []transcriptLine) string {
   326→	for i := len(transcript) - 1; i >= 0; i-- {
   327→		if transcript[i].Type == transcriptTypeAssistant {
   328→			var msg assistantMessage
   329→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   330→				continue
   331→			}
   332→
   333→			for _, block := range msg.Content {
   334→				if block.Type == contentTypeText && block.Text != "" {
   335→					return block.Text
   336→				}
   337→			}
   338→		}
   339→	}
   340→	return ""
   341→}
   342→
   343→// findLastUserUUID finds the UUID of the last user message (that has string content)
   344→func findLastUserUUID(transcript []transcriptLine) string {
   345→	for i := len(transcript) - 1; i >= 0; i-- {
   346→		if transcript[i].Type == transcriptTypeUser {
   347→			var msg userMessage
   348→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   349→				continue
   350→			}
   351→			// Only count messages with string content (not tool results)
   352→			if _, ok := msg.Content.(string); ok {
   353→				return transcript[i].UUID
   354→			}
   355→		}
   356→	}
   357→	return ""
   358→}
   359→
   360→// filterTranscriptAfterUUID returns transcript lines after the given UUID
   361→func filterTranscriptAfterUUID(transcript []transcriptLine, uuid string) []transcriptLine {
   362→	if uuid == "" {
   363→		return transcript
   364→	}
   365→
   366→	foundIndex := -1
   367→	for i, line := range transcript {
   368→		if line.UUID == uuid {
   369→			foundIndex = i
   370→			break
   371→		}
   372→	}
   373→
   374→	if foundIndex == -1 || foundIndex == len(transcript)-1 {
   375→		return transcript
   376→	}
   377→
   378→	return transcript[foundIndex+1:]
   379→}
   380→
   381→// extractModifiedFiles extracts the list of files modified by tool calls
   382→func extractModifiedFiles(transcript []transcriptLine) []string {
   383→	fileSet := make(map[string]bool)
   384→	var files []string
   385→
   386→	for _, line := range transcript {
   387→		if line.Type == transcriptTypeAssistant {
   388→			var msg assistantMessage
   389→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   390→				continue
   391→			}
   392→
   393→			for _, block := range msg.Content {
   394→				if block.Type == "tool_use" {
   395→					isModifyTool := false
   396→					for _, name := range claudecode.FileModificationTools {
   397→						if block.Name == name {
   398→							isModifyTool = true
   399→							break
   400→						}
   401→					}
   402→
   403→					if isModifyTool {
   404→						var input toolInput
   405→						if err := json.Unmarshal(block.Input, &input); err != nil {
   406→							continue
   407→						}
   408→
   409→						file := input.FilePath
   410→						if file == "" {
   411→							file = input.NotebookPath
   412→						}
   413→
   414→						if file != "" && !fileSet[file] {
   415→							fileSet[file] = true
   416→							files = append(files, file)
   417→						}
   418→					}
   419→				}
   420→			}
   421→		}
   422→	}
   423→
   424→	return files
   425→}
   426→
   427→// extractKeyActions extracts key actions from the transcript for context file
   428→func extractKeyActions(transcript []transcriptLine, maxActions int) []string {
   429→	var keyActions []string
   430→
   431→	for _, line := range transcript {
   432→		if line.Type == transcriptTypeAssistant {
   433→			var msg assistantMessage
   434→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   435→				continue
   436→			}
   437→
   438→			for _, block := range msg.Content {
   439→				if block.Type == "tool_use" {
   440→					var input toolInput
   441→					_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing for display purposes
   442→
   443→					detail := input.Description
   444→					if detail == "" {
   445→						detail = input.Command
   446→					}
   447→					if detail == "" {
   448→						detail = input.FilePath
   449→					}
   450→					if detail == "" {
   451→						detail = input.Pattern
   452→					}
   453→
   454→					action := "- **" + block.Name + "**: " + detail
   455→					keyActions = append(keyActions, action)
   456→					if len(keyActions) >= maxActions {
   457→						return keyActions
   458→					}
   459→				}
   460→			}
   461→		}
   462→	}
   463→
   464→	return keyActions
   465→}
   466→
   467→// AgentTranscriptPath returns the path to a subagent's transcript file.
   468→// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
   469→// as the main transcript.
   470→func AgentTranscriptPath(transcriptDir, agentID string) string {
   471→	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
   472→}
   473→
   474→// toolResultBlock represents a tool_result in a user message
   475→type toolResultBlock struct {
   476→	Type      string `json:"type"`
   477→	ToolUseID string `json:"tool_use_id"`
   478→}
   479→
   480→// userMessageWithToolResults represents a user message that may contain tool results
   481→type userMessageWithToolResults struct {
   482→	Content []toolResultBlock `json:"content"`
   483→}
   484→
   485→// FindCheckpointUUID finds the UUID of the message containing the tool_result
   486→// for the given tool_use_id. This is used to find the checkpoint point for
   487→// transcript truncation when rewinding to a task.
   488→// Returns the UUID and true if found, empty string and false otherwise.
   489→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
   490→	for _, line := range transcript {
   491→		if line.Type != transcriptTypeUser {
   492→			continue
   493→		}
   494→
   495→		var msg userMessageWithToolResults
   496→		if err := json.Unmarshal(line.Message, &msg); err != nil {
   497→			continue
   498→		}
   499→
   500→		for _, block := range msg.Content {
   501→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
   502→				return line.UUID, true
   503→			}
   504→		}
   505→	}
   506→	return "", false
   507→}
   508→
   509→// TruncateTranscriptAtUUID returns transcript lines up to and including the
   510→// line with the given UUID. If the UUID is not found or is empty, returns
   511→// the entire transcript.
   512→//
   513→//nolint:revive // Exported for testing purposes
   514→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
   515→	if uuid == "" {
   516→		return transcript
   517→	}
   518→
   519→	for i, line := range transcript {
   520→		if line.UUID == uuid {
   521→			return transcript[:i+1]
   522→		}
   523→	}
   524→
   525→	// UUID not found, return full transcript
   526→	return transcript
   527→}
   528→
   529→// writeTranscript writes transcript lines to a file in JSONL format.
   530→func writeTranscript(path string, transcript []transcriptLine) error {
   531→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
   532→	if err != nil {
   533→		return fmt.Errorf("failed to create file: %w", err)
   534→	}
   535→	defer func() { _ = file.Close() }()
   536→
   537→	for _, line := range transcript {
   538→		data, err := json.Marshal(line)
   539→		if err != nil {
   540→			return fmt.Errorf("failed to marshal line: %w", err)
   541→		}
   542→		if _, err := file.Write(data); err != nil {
   543→			return fmt.Errorf("failed to write line: %w", err)
   544→		}
   545→		if _, err := file.WriteString("\n"); err != nil {
   546→			return fmt.Errorf("failed to write newline: %w", err)
   547→		}
   548→	}
   549→
   550→	return nil
