package cli

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"entire.io/cli/cmd/entire/cli/agent/claudecode"
	"entire.io/cli/cmd/entire/cli/textutil"
)

// Transcript message type constants
const (
	transcriptTypeUser      = "user"
	transcriptTypeAssistant = "assistant"
	contentTypeText         = "text"
)

// parseTranscript reads and parses a Claude Code transcript file.
// Uses bufio.Reader to handle arbitrarily long lines.
func parseTranscript(path string) ([]transcriptLine, error) {
	file, err := os.Open(path) //nolint:gosec // Reading from controlled git metadata path
	if err != nil {
		return nil, err
	}
	defer func() { _ = file.Close() }()

	var lines []transcriptLine
	reader := bufio.NewReader(file)

	for {
		lineBytes, err := reader.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return nil, fmt.Errorf("failed to read transcript: %w", err)
		}

		// Handle empty line or EOF without content
		if len(lineBytes) == 0 {
			if err == io.EOF {
				break
			}
			continue
		}

		var line transcriptLine
		if err := json.Unmarshal(lineBytes, &line); err == nil {
			lines = append(lines, line)
		}

		if err == io.EOF {
			break
		}
	}

	return lines, nil
}

// parseTranscriptFromLine reads and parses a transcript file starting from a specific line.
// Uses bufio.Reader to handle arbitrarily long lines.
// Returns:
//   - lines: parsed transcript lines from startLine onwards (malformed lines skipped)
//   - totalLines: total number of lines in the file (including malformed ones)
//   - error: any error encountered during reading
//
// The startLine parameter is 0-indexed (startLine=0 reads from the beginning).
// This is useful for incremental parsing when you've already processed some lines.
func parseTranscriptFromLine(path string, startLine int) ([]transcriptLine, int, error) {
	file, err := os.Open(path) //nolint:gosec // path is a controlled transcript file path
	if err != nil {
		return nil, 0, fmt.Errorf("failed to open transcript: %w", err)
	}
	defer func() { _ = file.Close() }()

	var lines []transcriptLine
	reader := bufio.NewReader(file)

	totalLines := 0
	for {
		lineBytes, err := reader.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return nil, 0, fmt.Errorf("failed to read transcript: %w", err)
		}

		// Handle empty line or EOF without content
		if len(lineBytes) == 0 {
			if err == io.EOF {
				break
			}
			continue
		}

		// Count all lines for totalLines, but only parse after startLine
		if totalLines >= startLine {
			var line transcriptLine
			if err := json.Unmarshal(lineBytes, &line); err == nil {
				lines = append(lines, line)
			}
		}
		totalLines++

		if err == io.EOF {
			break
		}
	}

	return lines, totalLines, nil
}

// parseTranscriptFromBytes parses transcript content from a byte slice.
// Uses bufio.Reader to handle arbitrarily long lines.
func parseTranscriptFromBytes(content []byte) ([]transcriptLine, error) {
	var lines []transcriptLine
	reader := bufio.NewReader(bytes.NewReader(content))

	for {
		lineBytes, err := reader.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return nil, fmt.Errorf("failed to read transcript: %w", err)
		}

		// Handle empty line or EOF without content
		if len(lineBytes) == 0 {
			if err == io.EOF {
				break
			}
			continue
		}

		var line transcriptLine
		if err := json.Unmarshal(lineBytes, &line); err == nil {
			lines = append(lines, line)
		}

		if err == io.EOF {
			break
		}
	}

	return lines, nil
}

// PromptResponsePair represents a user prompt and the assistant's responses.
// Used for extracting all interactions from a transcript.
type PromptResponsePair struct {
	Prompt    string
	Responses []string // Multiple responses can occur between tool calls
	Files     []string
}

// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
// Returns pairs in chronological order (oldest first).
// Each pair contains the user's prompt, assistant's text response, and files modified.
func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
	var pairs []PromptResponsePair

	// Find all user prompts (messages with string content, not tool results)
	var userIndices []int
	for i, line := range transcript {
		if line.Type == transcriptTypeUser {
			var msg userMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}
			// Only count messages with string content (real user prompts)
			if _, ok := msg.Content.(string); ok {
				userIndices = append(userIndices, i)
			} else if arr, ok := msg.Content.([]interface{}); ok {
				// Check if array has text blocks (also a real user prompt)
				for _, item := range arr {
					if m, ok := item.(map[string]interface{}); ok {
						if m["type"] == contentTypeText {
							userIndices = append(userIndices, i)
							break
						}
					}
				}
			}
		}
	}

	// For each user prompt, extract the prompt text, following assistant response, and files
	for idx, userIdx := range userIndices {
		// Determine the range for this prompt's conversation
		endIdx := len(transcript)
		if idx < len(userIndices)-1 {
			endIdx = userIndices[idx+1]
		}

		// Extract prompt text
		prompt := extractUserPromptAt(transcript, userIdx)
		if prompt == "" {
			continue
		}

		// Extract assistant responses and files from this range
		slice := transcript[userIdx:endIdx]
		responses := extractAssistantResponses(slice)
		files := extractModifiedFiles(slice)

		pairs = append(pairs, PromptResponsePair{
			Prompt:    prompt,
			Responses: responses,
			Files:     files,
		})
	}

	return pairs
}

// extractUserPromptAt extracts the user prompt at the given index.
// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
func extractUserPromptAt(transcript []transcriptLine, idx int) string {
	if idx >= len(transcript) || transcript[idx].Type != transcriptTypeUser {
		return ""
	}

	var msg userMessage
	if err := json.Unmarshal(transcript[idx].Message, &msg); err != nil {
		return ""
	}

	// Handle string content
	if str, ok := msg.Content.(string); ok {
		return textutil.StripIDEContextTags(str)
	}

	// Handle array content (only if it contains text blocks)
	if arr, ok := msg.Content.([]interface{}); ok {
		var texts []string
		for _, item := range arr {
			if m, ok := item.(map[string]interface{}); ok {
				if m["type"] == contentTypeText {
					if text, ok := m["text"].(string); ok {
						texts = append(texts, text)
					}
				}
			}
		}
		if len(texts) > 0 {
			return textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
		}
	}

	return ""
}

// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
// A single prompt can trigger multiple assistant responses interspersed with tool calls.
func extractAssistantResponses(transcript []transcriptLine) []string {
	var texts []string
	for _, line := range transcript {
		if line.Type == transcriptTypeAssistant {
			var msg assistantMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}

			for _, block := range msg.Content {
				if block.Type == contentTypeText && block.Text != "" {
					texts = append(texts, block.Text)
				}
			}
		}
	}
	return texts
}

// extractUserPrompts extracts all user messages from the transcript in order.
// Only considers messages with string content (not tool results).
// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
func extractUserPrompts(transcript []transcriptLine) []string {
	var prompts []string
	for i := range transcript {
		if transcript[i].Type != transcriptTypeUser {
			continue
		}
		var msg userMessage
		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
			continue
		}

		// Handle string content
		if str, ok := msg.Content.(string); ok {
			prompts = append(prompts, textutil.StripIDEContextTags(str))
			continue
		}

		// Handle array content (only if it contains text blocks)
		if arr, ok := msg.Content.([]interface{}); ok {
			var texts []string
			for _, item := range arr {
				if m, ok := item.(map[string]interface{}); ok {
					if m["type"] == contentTypeText {
						if text, ok := m["text"].(string); ok {
							texts = append(texts, text)
						}
					}
				}
			}
			if len(texts) > 0 {
				prompts = append(prompts, textutil.StripIDEContextTags(strings.Join(texts, "\n\n")))
			}
		}
	}
	return prompts
}

// extractLastUserPrompt extracts the last user message from the transcript.
// Only considers messages with string content (not tool results).
// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
func extractLastUserPrompt(transcript []transcriptLine) string {
	prompts := extractUserPrompts(transcript)
	if len(prompts) == 0 {
		return ""
	}
	return prompts[len(prompts)-1]
}

// extractLastAssistantMessage extracts the last text message from the assistant
func extractLastAssistantMessage(transcript []transcriptLine) string {
	for i := len(transcript) - 1; i >= 0; i-- {
		if transcript[i].Type == transcriptTypeAssistant {
			var msg assistantMessage
			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
				continue
			}

			for _, block := range msg.Content {
				if block.Type == contentTypeText && block.Text != "" {
					return block.Text
				}
			}
		}
	}
	return ""
}

// findLastUserUUID finds the UUID of the last user message (that has string content)
func findLastUserUUID(transcript []transcriptLine) string {
	for i := len(transcript) - 1; i >= 0; i-- {
		if transcript[i].Type == transcriptTypeUser {
			var msg userMessage
			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
				continue
			}
			// Only count messages with string content (not tool results)
			if _, ok := msg.Content.(string); ok {
				return transcript[i].UUID
			}
		}
	}
	return ""
}

// filterTranscriptAfterUUID returns transcript lines after the given UUID
func filterTranscriptAfterUUID(transcript []transcriptLine, uuid string) []transcriptLine {
	if uuid == "" {
		return transcript
	}

	foundIndex := -1
	for i, line := range transcript {
		if line.UUID == uuid {
			foundIndex = i
			break
		}
	}

	if foundIndex == -1 || foundIndex == len(transcript)-1 {
		return transcript
	}

	return transcript[foundIndex+1:]
}

// extractModifiedFiles extracts the list of files modified by tool calls
func extractModifiedFiles(transcript []transcriptLine) []string {
	fileSet := make(map[string]bool)
	var files []string

	for _, line := range transcript {
		if line.Type == transcriptTypeAssistant {
			var msg assistantMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}

			for _, block := range msg.Content {
				if block.Type == "tool_use" {
					isModifyTool := false
					for _, name := range claudecode.FileModificationTools {
						if block.Name == name {
							isModifyTool = true
							break
						}
					}

					if isModifyTool {
						var input toolInput
						if err := json.Unmarshal(block.Input, &input); err != nil {
							continue
						}

						file := input.FilePath
						if file == "" {
							file = input.NotebookPath
						}

						if file != "" && !fileSet[file] {
							fileSet[file] = true
							files = append(files, file)
						}
					}
				}
			}
		}
	}

	return files
}

// extractKeyActions extracts key actions from the transcript for context file
func extractKeyActions(transcript []transcriptLine, maxActions int) []string {
	var keyActions []string

	for _, line := range transcript {
		if line.Type == transcriptTypeAssistant {
			var msg assistantMessage
			if err := json.Unmarshal(line.Message, &msg); err != nil {
				continue
			}

			for _, block := range msg.Content {
				if block.Type == "tool_use" {
					var input toolInput
					_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing for display purposes

					detail := input.Description
					if detail == "" {
						detail = input.Command
					}
					if detail == "" {
						detail = input.FilePath
					}
					if detail == "" {
						detail = input.Pattern
					}

					action := "- **" + block.Name + "**: " + detail
					keyActions = append(keyActions, action)
					if len(keyActions) >= maxActions {
						return keyActions
					}
				}
			}
		}
	}

	return keyActions
}

// AgentTranscriptPath returns the path to a subagent's transcript file.
// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
// as the main transcript.
func AgentTranscriptPath(transcriptDir, agentID string) string {
	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
}

// toolResultBlock represents a tool_result in a user message
type toolResultBlock struct {
	Type      string `json:"type"`
	ToolUseID string `json:"tool_use_id"`
}

// userMessageWithToolResults represents a user message that may contain tool results
type userMessageWithToolResults struct {
	Content []toolResultBlock `json:"content"`
}

// FindCheckpointUUID finds the UUID of the message containing the tool_result
// for the given tool_use_id. This is used to find the checkpoint point for
// transcript truncation when rewinding to a task.
// Returns the UUID and true if found, empty string and false otherwise.
func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
	for _, line := range transcript {
		if line.Type != transcriptTypeUser {
			continue
		}

		var msg userMessageWithToolResults
		if err := json.Unmarshal(line.Message, &msg); err != nil {
			continue
		}

		for _, block := range msg.Content {
			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
				return line.UUID, true
			}
		}
	}
	return "", false
}

// TruncateTranscriptAtUUID returns transcript lines up to and including the
// line with the given UUID. If the UUID is not found or is empty, returns
// the entire transcript.
//
//nolint:revive // Exported for testing purposes
func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
	if uuid == "" {
		return transcript
	}

	for i, line := range transcript {
		if line.UUID == uuid {
			return transcript[:i+1]
		}
	}

	// UUID not found, return full transcript
	return transcript
}

// writeTranscript writes transcript lines to a file in JSONL format.
func writeTranscript(path string, transcript []transcriptLine) error {
	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
	if err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	defer func() { _ = file.Close() }()

	for _, line := range transcript {
		data, err := json.Marshal(line)
		if err != nil {
			return fmt.Errorf("failed to marshal line: %w", err)
		}
		if _, err := file.Write(data); err != nil {
			return fmt.Errorf("failed to write line: %w", err)
		}
		if _, err := file.WriteString("\n"); err != nil {
			return fmt.Errorf("failed to write newline: %w", err)
		}
	}

	return nil
}

// TranscriptPosition contains the position information for a transcript file.
type TranscriptPosition struct {
	LastUUID  string // Last non-empty UUID (from user/assistant messages)
	LineCount int    // Total number of lines
}

// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
// Returns empty position if file doesn't exist or is empty.
// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
func GetTranscriptPosition(path string) (TranscriptPosition, error) {
	if path == "" {
		return TranscriptPosition{}, nil
	}

	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
	if err != nil {
		if os.IsNotExist(err) {
			return TranscriptPosition{}, nil
		}
		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
	}
	defer func() { _ = file.Close() }()

	var pos TranscriptPosition
	reader := bufio.NewReader(file)

	for {
		lineBytes, err := reader.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
		}

		if len(lineBytes) == 0 {
			if err == io.EOF {
				break
			}
			continue
		}

		pos.LineCount++

		// Parse line to extract UUID (only from user/assistant messages, not summaries)
		var line transcriptLine
		if err := json.Unmarshal(lineBytes, &line); err == nil {
			if line.UUID != "" {
				pos.LastUUID = line.UUID
			}
		}

		if err == io.EOF {
			break
		}
	}

	return pos, nil
}

// Package checkpoint provides types and interfaces for checkpoint storage.
//
// A Checkpoint captures a point-in-time within a session, containing either
// full state (Temporary) or metadata with a commit reference (Committed).
//
// See docs/architecture/sessions-and-checkpoints.md for the full domain model.
package checkpoint

import (
	"context"
	"errors"
	"time"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"

	"github.com/go-git/go-git/v5/plumbing"
)

// Errors returned by checkpoint operations.
var (
	// ErrCheckpointNotFound is returned when a checkpoint ID doesn't exist.
	ErrCheckpointNotFound = errors.New("checkpoint not found")

	// ErrNoTranscript is returned when a checkpoint exists but has no transcript.
	ErrNoTranscript = errors.New("no transcript found for checkpoint")
)

// Checkpoint represents a save point within a session.
type Checkpoint struct {
	// ID is the unique checkpoint identifier
	ID string

	// SessionID is the session this checkpoint belongs to
	SessionID string

	// Timestamp is when this checkpoint was created
	Timestamp time.Time

	// Type indicates temporary (full state) or committed (metadata only)
	Type Type

	// Message is a human-readable description of the checkpoint
	Message string
}

// Type indicates the storage location and lifecycle of a checkpoint.
type Type int

const (
	// Temporary checkpoints contain full state (code + metadata) and are stored
	// on shadow branches (entire/<commit-hash>). Used for intra-session rewind.
	Temporary Type = iota

	// Committed checkpoints contain metadata + commit reference and are stored
	// on the entire/sessions branch. They are the permanent record.
	Committed
)

// Store provides low-level primitives for reading and writing checkpoints.
// This is used by strategies to implement their storage approach.
//
// The interface matches the GitStore implementation signatures directly:
// - WriteTemporary takes WriteTemporaryOptions and returns a result with commit hash and skip status
// - ReadTemporary takes baseCommit (not sessionID) since shadow branches are keyed by commit
// - List methods return implementation-specific info types for richer data
type Store interface {
	// WriteTemporary writes a temporary checkpoint (full state) to a shadow branch.
	// Shadow branches are named entire/<base-commit-short-hash>.
	// Returns a result containing the commit hash and whether the checkpoint was skipped.
	// Checkpoints are skipped (deduplicated) when the tree hash matches the previous checkpoint.
	WriteTemporary(ctx context.Context, opts WriteTemporaryOptions) (WriteTemporaryResult, error)

	// ReadTemporary reads the latest checkpoint from a shadow branch.
	// baseCommit is the commit hash the session is based on.
	// Returns nil, nil if the shadow branch doesn't exist.
	ReadTemporary(ctx context.Context, baseCommit string) (*ReadTemporaryResult, error)

	// ListTemporary lists all shadow branches with their checkpoint info.
	ListTemporary(ctx context.Context) ([]TemporaryInfo, error)

	// WriteCommitted writes a committed checkpoint to the entire/sessions branch.
	// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
	WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error

	// ReadCommitted reads a committed checkpoint by ID.
	// Returns nil, nil if the checkpoint does not exist.
	ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*ReadCommittedResult, error)

	// ListCommitted lists all committed checkpoints.
	ListCommitted(ctx context.Context) ([]CommittedInfo, error)
}

// WriteTemporaryResult contains the result of writing a temporary checkpoint.
type WriteTemporaryResult struct {
	// CommitHash is the hash of the created or existing checkpoint commit
	CommitHash plumbing.Hash

	// Skipped is true if the checkpoint was skipped due to no changes
	// (tree hash matched the previous checkpoint)
	Skipped bool
}

// WriteTemporaryOptions contains options for writing a temporary checkpoint.
type WriteTemporaryOptions struct {
	// SessionID is the session identifier
	SessionID string

	// BaseCommit is the commit hash this session is based on
	BaseCommit string

	// ModifiedFiles are files that have been modified (relative paths)
	ModifiedFiles []string

	// NewFiles are files that have been created (relative paths)
	NewFiles []string

	// DeletedFiles are files that have been deleted (relative paths)
	DeletedFiles []string

	// MetadataDir is the relative path to the metadata directory
	MetadataDir string

	// MetadataDirAbs is the absolute path to the metadata directory
	MetadataDirAbs string

	// CommitMessage is the commit subject line
	CommitMessage string

	// AuthorName is the name to use for commits
	AuthorName string

	// AuthorEmail is the email to use for commits
	AuthorEmail string

	// IsFirstCheckpoint indicates if this is the first checkpoint of the session
	// When true, all working directory files are captured (not just modified)
	IsFirstCheckpoint bool
}

// ReadTemporaryResult contains the result of reading a temporary checkpoint.
type ReadTemporaryResult struct {
	// CommitHash is the hash of the checkpoint commit
	CommitHash plumbing.Hash

	// TreeHash is the hash of the tree containing the checkpoint state
	TreeHash plumbing.Hash

	// SessionID is the session identifier from the commit trailer
	SessionID string

	// MetadataDir is the metadata directory path from the commit trailer
	MetadataDir string

	// Timestamp is when the checkpoint was created
	Timestamp time.Time
}

// TemporaryInfo contains summary information about a shadow branch.
type TemporaryInfo struct {
	// BranchName is the full branch name (e.g., "entire/abc1234")
	BranchName string

	// BaseCommit is the short commit hash this branch is based on
	BaseCommit string

	// LatestCommit is the hash of the latest commit on the branch
	LatestCommit plumbing.Hash

	// SessionID is the session identifier from the latest commit
	SessionID string

	// Timestamp is when the latest checkpoint was created
	Timestamp time.Time
}

// WriteCommittedOptions contains options for writing a committed checkpoint.
type WriteCommittedOptions struct {
	// CheckpointID is the stable 12-hex-char identifier
	CheckpointID id.CheckpointID

	// SessionID is the session identifier
	SessionID string

	// Strategy is the name of the strategy that created this checkpoint
	Strategy string

	// Branch is the branch name where the checkpoint was created (empty if detached HEAD)
	Branch string

	// Transcript is the session transcript content (full.jsonl)
	Transcript []byte

	// Prompts contains user prompts from the session
	Prompts []string

	// Context is the generated context.md content
	Context []byte

	// FilesTouched are files modified during the session
	FilesTouched []string

	// CheckpointsCount is the number of checkpoints in this session
	CheckpointsCount int

	// EphemeralBranch is the shadow branch name (for manual-commit strategy)
	EphemeralBranch string

	// AuthorName is the name to use for commits
	AuthorName string

	// AuthorEmail is the email to use for commits
	AuthorEmail string

	// MetadataDir is a directory containing additional metadata files to copy
	// If set, all files in this directory will be copied to the checkpoint path
	// This is useful for copying task metadata files, subagent transcripts, etc.
	MetadataDir string

	// Task checkpoint fields (for auto-commit strategy task checkpoints)
	IsTask    bool   // Whether this is a task checkpoint
	ToolUseID string // Tool use ID for task checkpoints

	// Additional task checkpoint fields for subagent checkpoints
	AgentID                string // Subagent identifier
	CheckpointUUID         string // UUID for transcript truncation when rewinding
	TranscriptPath         string // Path to session transcript file (alternative to in-memory Transcript)
	SubagentTranscriptPath string // Path to subagent's transcript file

	// Incremental checkpoint fields
	IsIncremental       bool   // Whether this is an incremental checkpoint
	IncrementalSequence int    // Checkpoint sequence number
	IncrementalType     string // Tool type that triggered this checkpoint
	IncrementalData     []byte // Tool input payload for this checkpoint

	// Commit message fields (used for task checkpoints)
	CommitSubject string // Subject line for the metadata commit (overrides default)

	// Agent identifies the agent that created this checkpoint (e.g., "Claude Code", "Cursor")
	Agent agent.AgentType

	// Transcript position at checkpoint start - tracks what was added during this checkpoint
	TranscriptUUIDAtStart  string // Last UUID when checkpoint started
	TranscriptLinesAtStart int    // Line count when checkpoint started

	// TokenUsage contains the token usage for this checkpoint
	TokenUsage *agent.TokenUsage
}

// ReadCommittedResult contains the result of reading a committed checkpoint.
type ReadCommittedResult struct {
	// Metadata contains the checkpoint metadata
	Metadata CommittedMetadata

	// Transcript is the session transcript content (most recent session)
	Transcript []byte

	// Prompts contains user prompts (most recent session)
	Prompts string

	// Context is the context.md content
	Context string

	// ArchivedSessions contains transcripts from previous sessions when multiple
	// sessions were condensed to the same checkpoint. Ordered from oldest to newest
	// (1/, 2/, etc.). The root-level Transcript is the most recent session.
	ArchivedSessions []ArchivedSession
}

// ArchivedSession contains transcript data from a previous session
// that was archived when multiple sessions contributed to the same checkpoint.
type ArchivedSession struct {
	// SessionID is the session identifier for this archived session
	SessionID string

	// Transcript is the session transcript content
	Transcript []byte

	// Prompts contains user prompts from this session
	Prompts string

	// FolderIndex is the archive folder number (1, 2, etc.)
	FolderIndex int
}

// CommittedInfo contains summary information about a committed checkpoint.
type CommittedInfo struct {
	// CheckpointID is the stable 12-hex-char identifier
	CheckpointID id.CheckpointID

	// SessionID is the session identifier (most recent session for multi-session checkpoints)
	SessionID string

	// CreatedAt is when the checkpoint was created
	CreatedAt time.Time

	// CheckpointsCount is the total number of checkpoints across all sessions
	CheckpointsCount int

	// FilesTouched are files modified during all sessions
	FilesTouched []string

	// Agent identifies the agent that created this checkpoint
	Agent agent.AgentType

	// IsTask indicates if this is a task checkpoint
	IsTask bool

	// ToolUseID is the tool use ID for task checkpoints
	ToolUseID string

	// Multi-session support
	SessionCount int      // Number of sessions (1 if single session)
	SessionIDs   []string // All session IDs that contributed
}

// CommittedMetadata contains the metadata stored in metadata.json for each checkpoint.
type CommittedMetadata struct {
	CheckpointID     id.CheckpointID `json:"checkpoint_id"`
	SessionID        string          `json:"session_id"`
	Strategy         string          `json:"strategy"`
	CreatedAt        time.Time       `json:"created_at"`
	Branch           string          `json:"branch,omitempty"` // Branch where checkpoint was created (empty if detached HEAD)
	CheckpointsCount int             `json:"checkpoints_count"`
	FilesTouched     []string        `json:"files_touched"`

	// Agent identifies the agent that created this checkpoint (e.g., "Claude Code", "Cursor")
	// For multi-session checkpoints, this is the first agent (see Agents for all)
	Agent  agent.AgentType   `json:"agent,omitempty"`
	Agents []agent.AgentType `json:"agents,omitempty"` // All agents that contributed (multi-session, deduplicated)

	// Multi-session support: when multiple sessions contribute to the same checkpoint
	SessionCount int      `json:"session_count,omitempty"` // Number of sessions (1 if omitted for backwards compat)
	SessionIDs   []string `json:"session_ids,omitempty"`   // All session IDs that contributed

	// Task checkpoint fields (only populated for task checkpoints)
	IsTask    bool   `json:"is_task,omitempty"`
	ToolUseID string `json:"tool_use_id,omitempty"`

	// Transcript position at checkpoint start - tracks what was added during this checkpoint
	TranscriptUUIDAtStart  string `json:"transcript_uuid_at_start,omitempty"`  // Last UUID when checkpoint started
	TranscriptLinesAtStart int    `json:"transcript_lines_at_start,omitempty"` // Line count when checkpoint started

	// Token usage for this checkpoint
	TokenUsage *agent.TokenUsage `json:"token_usage,omitempty"`
}

// Info provides summary information for listing checkpoints.
// This is the generic checkpoint info type.
type Info struct {
	// ID is the checkpoint identifier
	ID string

	// SessionID identifies the session
	SessionID string

	// Type indicates temporary or committed
	Type Type

	// CreatedAt is when the checkpoint was created
	CreatedAt time.Time

	// Message is a summary description
	Message string
}

// WriteTemporaryTaskOptions contains options for writing a task checkpoint.
// Task checkpoints are created when a subagent completes and contain both
// code changes and task-specific metadata.
type WriteTemporaryTaskOptions struct {
	// SessionID is the session identifier
	SessionID string

	// BaseCommit is the commit hash this session is based on
	BaseCommit string

	// ToolUseID is the unique identifier for this Task tool invocation
