   171→// FormatCondensedTranscript formats a SummaryInput into a human-readable string for LLM.
   172→// The format is:
   173→//
   174→//	[User] user prompt here
   175→//
   176→//	[Assistant] assistant response here
   177→//
   178→//	[Tool] ToolName: description or file path
   179→func FormatCondensedTranscript(input SummaryInput) string {
   180→	var sb strings.Builder
   181→
   182→	for i, entry := range input.Transcript {
   183→		if i > 0 {
   184→			sb.WriteString("\n")
   185→		}
   186→
   187→		switch entry.Type {
   188→		case EntryTypeUser:
   189→			sb.WriteString("[User] ")
   190→			sb.WriteString(entry.Content)
   191→			sb.WriteString("\n")
   192→		case EntryTypeAssistant:
   193→			sb.WriteString("[Assistant] ")
   194→			sb.WriteString(entry.Content)
   195→			sb.WriteString("\n")
   196→		case EntryTypeTool:
   197→			sb.WriteString("[Tool] ")
   198→			sb.WriteString(entry.ToolName)
   199→			if entry.ToolDetail != "" {
   200→				sb.WriteString(": ")
   201→				sb.WriteString(entry.ToolDetail)
   202→			}
   203→			sb.WriteString("\n")
   204→		}
   205→	}
   206→
   207→	if len(input.FilesTouched) > 0 {
   208→		sb.WriteString("\n[Files Modified]\n")
   209→		for _, file := range input.FilesTouched {
   210→			fmt.Fprintf(&sb, "- %s\n", file)
   211→		}
   212→	}
   213→
   214→	return sb.String()
   215→}
