   309→+Return a JSON object with this exact structure:
   310→+{
   311→+  "intent": "What the user was trying to accomplish (1-2 sentences)",
   312→+  "outcome": "What was actually achieved (1-2 sentences)",
   313→+  "learnings": {
   314→+    "repo": ["Codebase-specific patterns, conventions, or gotchas discovered"],
   315→+    "code": [{"path": "file/path.go", "line": 42, "end_line": 56, "finding": "What was learned"}],
   316→+    "workflow": ["General development practices or tool usage insights"]
   317→+  },
   318→+  "friction": ["Problems, blockers, or annoyances encountered"],
   319→+  "open_items": ["Tech debt, unfinished work, or things to revisit later"]
   320→+}
   321→+
   322→+Guidelines:
   323→+- Be concise but specific
   324→+- Include line numbers for code learnings when the transcript references specific lines
   325→+- Friction should capture both blockers and minor annoyances
   326→+- Open items are things intentionally deferred, not failures
   327→+- Empty arrays are fine if a category doesn't apply
   328→+- Return ONLY the JSON object, no markdown formatting or explanation`
   329→+
   330→+// ClaudeCLIGenerator generates summaries using the Claude CLI.
   331→+type ClaudeCLIGenerator struct {
   332→+	// CommandRunner allows injection of the command execution for testing.
   333→+	// If nil, uses exec.CommandContext directly.
   334→+	CommandRunner func(ctx context.Context, name string, args ...string) *exec.Cmd
   335→+}
   336→+
   337→+// claudeCLIResponse represents the JSON response from the Claude CLI.
   338→+type claudeCLIResponse struct {
   339→+	Result string `json:"result"`
   340→+}
   341→+
   342→+// Generate creates a summary from checkpoint data by calling the Claude CLI.
   343→+func (g *ClaudeCLIGenerator) Generate(ctx context.Context, input SummaryInput) (*checkpoint.Summary, error) {
   344→+	// Format the transcript for the prompt
   345→+	transcriptText := FormatCondensedTranscript(input)
   346→+
   347→+	// Build the prompt
   348→+	prompt := BuildSummarizationPrompt(transcriptText)
   349→+
   350→+	// Execute the Claude CLI
   351→+	runner := g.CommandRunner
   352→+	if runner == nil {
   353→+		runner = exec.CommandContext
   354→+	}
   355→+
   356→+	cmd := runner(ctx, "claude", "--print", "--output-format", "json")
   357→+
   358→+	// Pass prompt via stdin
   359→+	cmd.Stdin = strings.NewReader(prompt)
   360→+
   361→+	var stdout, stderr bytes.Buffer
   362→+	cmd.Stdout = &stdout
   363→+	cmd.Stderr = &stderr
   364→+
   365→+	err := cmd.Run()
   366→+	if err != nil {
   367→+		// Check if the command was not found
   368→+		var execErr *exec.Error
   369→+		if errors.As(err, &execErr) {
   370→+			return nil, fmt.Errorf("claude CLI not found: %w", err)
   371→+		}
   372→+
   373→+		// Check for exit error
   374→+		var exitErr *exec.ExitError
   375→+		if errors.As(err, &exitErr) {
   376→+			return nil, fmt.Errorf("claude CLI failed (exit %d): %s", exitErr.ExitCode(), stderr.String())
   377→+		}
   378→+
   379→+		return nil, fmt.Errorf("failed to run claude CLI: %w", err)
   380→+	}
   381→+
   382→+	// Parse the CLI response
   383→+	var cliResponse claudeCLIResponse
   384→+	if err := json.Unmarshal(stdout.Bytes(), &cliResponse); err != nil {
   385→+		return nil, fmt.Errorf("failed to parse claude CLI response: %w", err)
   386→+	}
   387→+
   388→+	// The result field contains the actual JSON summary
   389→+	resultJSON := cliResponse.Result
   390→+
   391→+	// Try to extract JSON if it's wrapped in markdown code blocks
   392→+	resultJSON = extractJSONFromMarkdown(resultJSON)
   393→+
   394→+	// Parse the summary from the result
   395→+	var summary checkpoint.Summary
   396→+	if err := json.Unmarshal([]byte(resultJSON), &summary); err != nil {
   397→+		return nil, fmt.Errorf("failed to parse summary JSON: %w (response: %s)", err, resultJSON)
   398→+	}
   399→+
   400→+	return &summary, nil
   401→+}
   402→+
   403→+// BuildSummarizationPrompt creates the prompt for the Claude CLI.
   404→+func BuildSummarizationPrompt(transcriptText string) string {
   405→+	return fmt.Sprintf(summarizationPromptTemplate, transcriptText)
   406→+}
   407→+
   408→+// extractJSONFromMarkdown attempts to extract JSON from markdown code blocks.
   409→+// If the input is not wrapped in code blocks, it returns the input unchanged.
   410→+func extractJSONFromMarkdown(s string) string {
   411→+	s = strings.TrimSpace(s)
   412→+
   413→+	// Check for ```json ... ``` blocks
   414→+	if strings.HasPrefix(s, "```json") {
   415→+		s = strings.TrimPrefix(s, "```json")
   416→+		if idx := strings.LastIndex(s, "```"); idx != -1 {
   417→+			s = s[:idx]
   418→+		}
   419→+		return strings.TrimSpace(s)
   420→+	}
   421→+
   422→+	// Check for ``` ... ``` blocks
   423→+	if strings.HasPrefix(s, "```") {
   424→+		s = strings.TrimPrefix(s, "```")
   425→+		if idx := strings.LastIndex(s, "```"); idx != -1 {
   426→+			s = s[:idx]
   427→+		}
   428→+		return strings.TrimSpace(s)
   429→+	}
   430→+
   431→+	return s
   432→+}
