   275→// Only considers messages with string content (not tool results).
   276→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
   277→func extractUserPrompts(transcript []transcriptLine) []string {
   278→	var prompts []string
   279→	for i := range transcript {
