    13→// SummaryGenerator generates checkpoint summaries using an LLM.
    14→type SummaryGenerator interface {
    15→	// Generate creates a summary from checkpoint data.
    16→	// Returns the generated summary or an error if generation fails.
    17→	Generate(ctx context.Context, input SummaryInput) (*checkpoint.Summary, error)
    18→}
    19→
    20→// SummaryInput contains condensed checkpoint data for summarization.
    21→type SummaryInput struct {
    22→	// Transcript is the condensed transcript entries
    23→	Transcript []TranscriptEntry
    24→
    25→	// FilesTouched are the files modified during the session
    26→	FilesTouched []string
    27→}
    28→
    29→// TranscriptEntryType represents the type of a transcript entry.
    30→type TranscriptEntryType string
    31→
    32→const (
    33→	// EntryTypeUser indicates a user prompt entry.
    34→	EntryTypeUser TranscriptEntryType = "user"
    35→	// EntryTypeAssistant indicates an assistant response entry.
    36→	EntryTypeAssistant TranscriptEntryType = "assistant"
    37→	// EntryTypeTool indicates a tool call entry.
    38→	EntryTypeTool TranscriptEntryType = "tool"
    39→)
    40→
    41→// TranscriptEntry represents one item in the condensed transcript.
    42→type TranscriptEntry struct {
    43→	// Type is the entry type (user, assistant, tool)
    44→	Type TranscriptEntryType
    45→
    46→	// Content is the text content for user/assistant entries
    47→	Content string
    48→
    49→	// ToolName is the name of the tool (for tool entries)
    50→	ToolName string
    51→
    52→	// ToolDetail is a description or file path (for tool entries)
    53→	ToolDetail string
    54→}
    55→
    56→// BuildCondensedTranscript extracts a condensed view of the transcript.
    57→// It processes user prompts, assistant responses, and tool calls into
    58→// a simplified format suitable for LLM summarization.
    59→func BuildCondensedTranscript(transcript []transcriptLine) []TranscriptEntry {
    60→	var entries []TranscriptEntry
    61→
    62→	for _, line := range transcript {
    63→		switch line.Type {
    64→		case transcriptTypeUser:
    65→			if entry := extractUserEntry(line); entry != nil {
    66→				entries = append(entries, *entry)
    67→			}
    68→		case transcriptTypeAssistant:
    69→			assistantEntries := extractAssistantEntries(line)
    70→			entries = append(entries, assistantEntries...)
    71→		}
    72→	}
    73→
    74→	return entries
    75→}
    76→
    77→// extractUserEntry extracts a user entry from a transcript line.
    78→// Returns nil if the line doesn't contain a valid user prompt.
    79→func extractUserEntry(line transcriptLine) *TranscriptEntry {
    80→	var msg userMessage
    81→	if err := json.Unmarshal(line.Message, &msg); err != nil {
    82→		return nil
    83→	}
    84→
    85→	// Handle string content
    86→	if str, ok := msg.Content.(string); ok {
    87→		cleaned := textutil.StripIDEContextTags(str)
    88→		if cleaned == "" {
    89→			return nil
    90→		}
    91→		return &TranscriptEntry{
    92→			Type:    EntryTypeUser,
    93→			Content: cleaned,
    94→		}
    95→	}
    96→
    97→	// Handle array content (only if it contains text blocks)
    98→	if arr, ok := msg.Content.([]interface{}); ok {
    99→		var texts []string
   100→		for _, item := range arr {
   101→			if m, ok := item.(map[string]interface{}); ok {
   102→				if m["type"] == contentTypeText {
   103→					if text, ok := m["text"].(string); ok {
   104→						texts = append(texts, text)
   105→					}
   106→				}
   107→			}
   108→		}
   109→		if len(texts) > 0 {
   110→			cleaned := textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   111→			if cleaned == "" {
   112→				return nil
   113→			}
   114→			return &TranscriptEntry{
   115→				Type:    EntryTypeUser,
   116→				Content: cleaned,
   117→			}
   118→		}
   119→	}
   120→
   121→	return nil
   122→}
   123→
   124→// extractAssistantEntries extracts assistant and tool entries from a transcript line.
   125→func extractAssistantEntries(line transcriptLine) []TranscriptEntry {
   126→	var msg assistantMessage
   127→	if err := json.Unmarshal(line.Message, &msg); err != nil {
   128→		return nil
   129→	}
   130→
   131→	var entries []TranscriptEntry
   132→
   133→	for _, block := range msg.Content {
   134→		switch block.Type {
   135→		case contentTypeText:
   136→			if block.Text != "" {
   137→				entries = append(entries, TranscriptEntry{
   138→					Type:    EntryTypeAssistant,
   139→					Content: block.Text,
   140→				})
   141→			}
   142→		case contentTypeToolUse:
   143→			var input toolInput
   144→			_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
   145→
   146→			detail := input.Description
   147→			if detail == "" {
   148→				detail = input.Command
   149→			}
   150→			if detail == "" {
   151→				detail = input.FilePath
   152→			}
   153→			if detail == "" {
   154→				detail = input.NotebookPath
   155→			}
   156→			if detail == "" {
   157→				detail = input.Pattern
   158→			}
   159→
   160→			entries = append(entries, TranscriptEntry{
   161→				Type:       EntryTypeTool,
   162→				ToolName:   block.Name,
   163→				ToolDetail: detail,
   164→			})
   165→		}
   166→	}
   167→
   168→	return entries
   169→}
   170→
   171→// FormatCondensedTranscript formats a SummaryInput into a human-readable string for LLM.
   172→// The format is:
   173→//
   174→//	[User] user prompt here
   175→//
   176→//	[Assistant] assistant response here
   177→//
   178→//	[Tool] ToolName: description or file path
   179→func FormatCondensedTranscript(input SummaryInput) string {
   180→	var sb strings.Builder
   181→
   182→	for i, entry := range input.Transcript {
   183→		if i > 0 {
   184→			sb.WriteString("\n")
   185→		}
   186→
   187→		switch entry.Type {
   188→		case EntryTypeUser:
   189→			sb.WriteString("[User] ")
   190→			sb.WriteString(entry.Content)
   191→			sb.WriteString("\n")
   192→		case EntryTypeAssistant:
   193→			sb.WriteString("[Assistant] ")
   194→			sb.WriteString(entry.Content)
   195→			sb.WriteString("\n")
   196→		case EntryTypeTool:
   197→			sb.WriteString("[Tool] ")
   198→			sb.WriteString(entry.ToolName)
   199→			if entry.ToolDetail != "" {
   200→				sb.WriteString(": ")
   201→				sb.WriteString(entry.ToolDetail)
   202→			}
   203→			sb.WriteString("\n")
   204→		}
   205→	}
   206→
   207→	if len(input.FilesTouched) > 0 {
   208→		sb.WriteString("\n[Files Modified]\n")
   209→		for _, file := range input.FilesTouched {
   210→			fmt.Fprintf(&sb, "- %s\n", file)
   211→		}
   212→	}
   213→
   214→	return sb.String()
   215→}
