   131→// writeTaskCheckpointEntries writes task-specific checkpoint entries and returns the task metadata path.
   132→func (s *GitStore) writeTaskCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (string, error) {
   133→	taskPath := basePath + "tasks/" + opts.ToolUseID + "/"
   134→
   135→	if opts.IsIncremental {
   136→		return s.writeIncrementalTaskCheckpoint(opts, taskPath, entries)
   137→	}
   138→	return s.writeFinalTaskCheckpoint(opts, taskPath, entries)
   139→}
   140→
   141→// writeIncrementalTaskCheckpoint writes an incremental checkpoint file during task execution.
   142→func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
   143→	checkpoint := incrementalCheckpointData{
   144→		Type:      opts.IncrementalType,
   145→		ToolUseID: opts.ToolUseID,
   146→		Timestamp: time.Now().UTC(),
   147→		Data:      opts.IncrementalData,
   148→	}
   149→	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
   150→	if err != nil {
   151→		return "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
   152→	}
   153→	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
   154→	if err != nil {
   155→		return "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
   156→	}
   157→
   158→	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
   159→	cpPath := taskPath + "checkpoints/" + cpFilename
   160→	entries[cpPath] = object.TreeEntry{
   161→		Name: cpPath,
   162→		Mode: filemode.Regular,
   163→		Hash: cpBlobHash,
   164→	}
   165→	return cpPath, nil
   166→}
   167→
   168→// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
   169→func (s *GitStore) writeFinalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
   170→	checkpoint := taskCheckpointData{
   171→		SessionID:      opts.SessionID,
   172→		ToolUseID:      opts.ToolUseID,
   173→		CheckpointUUID: opts.CheckpointUUID,
   174→		AgentID:        opts.AgentID,
   175→	}
   176→	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
   177→	if err != nil {
   178→		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
   179→	}
   180→	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
   181→	if err != nil {
   182→		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
   183→	}
   184→
   185→	checkpointFile := taskPath + "checkpoint.json"
   186→	entries[checkpointFile] = object.TreeEntry{
   187→		Name: checkpointFile,
   188→		Mode: filemode.Regular,
   189→		Hash: blobHash,
   190→	}
   191→
   192→	// Write subagent transcript if available
   193→	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
   194→		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
   195→		if readErr == nil {
   196→			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
   197→			if agentBlobErr == nil {
   198→				agentPath := taskPath + "agent-" + opts.AgentID + ".jsonl"
   199→				entries[agentPath] = object.TreeEntry{
   200→					Name: agentPath,
   201→					Mode: filemode.Regular,
   202→					Hash: agentBlobHash,
   203→				}
   204→			}
   205→		}
   206→	}
   207→
   208→	// Return task path without trailing slash
   209→	return taskPath[:len(taskPath)-1], nil
   210→}
