   321→// writeMetadataJSON writes the metadata.json file for the checkpoint.
   322→// If existingMetadata is provided, merges session info from the previous session(s).
   323→func (s *GitStore) writeMetadataJSON(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingMetadata *CommittedMetadata) error {
   324→	// Note: Agents array is only populated during multi-session merge (below).
   325→	// For single-session checkpoints, we only set Agent (singular).
   326→	metadata := CommittedMetadata{
   327→		CheckpointID:           opts.CheckpointID,
   328→		SessionID:              opts.SessionID,
   329→		Strategy:               opts.Strategy,
   330→		CreatedAt:              time.Now(),
   331→		Branch:                 opts.Branch,
   332→		CheckpointsCount:       opts.CheckpointsCount,
   333→		FilesTouched:           opts.FilesTouched,
   334→		Agent:                  opts.Agent,
   335→		Agents:                 nil, // Only set during multi-session merge
   336→		IsTask:                 opts.IsTask,
   337→		ToolUseID:              opts.ToolUseID,
   338→		SessionCount:           1,
   339→		SessionIDs:             []string{opts.SessionID},
   340→		TranscriptUUIDAtStart:  opts.TranscriptUUIDAtStart,
   341→		TranscriptLinesAtStart: opts.TranscriptLinesAtStart,
   342→		TokenUsage:             opts.TokenUsage,
   343→	}
   344→
   345→	// Merge with existing metadata if present (multi-session checkpoint)
   346→	if existingMetadata != nil {
   347→		// Get existing session count (default to 1 for backwards compat)
   348→		existingCount := existingMetadata.SessionCount
   349→		if existingCount == 0 {
   350→			existingCount = 1
   351→		}
   352→		metadata.SessionCount = existingCount + 1
   353→
   354→		// Merge session IDs
   355→		existingIDs := existingMetadata.SessionIDs
   356→		if len(existingIDs) == 0 {
   357→			// Backwards compat: old metadata only had SessionID
   358→			existingIDs = []string{existingMetadata.SessionID}
   359→		}
   360→		metadata.SessionIDs = append(metadata.SessionIDs[:0], existingIDs...)
   361→		metadata.SessionIDs = append(metadata.SessionIDs, opts.SessionID)
   362→
   363→		// Merge agents (deduplicated, preserving order)
   364→		existingAgents := existingMetadata.Agents
   365→		if len(existingAgents) == 0 && existingMetadata.Agent != "" {
   366→			// Backwards compat: old metadata only had Agent
   367→			existingAgents = []agent.AgentType{existingMetadata.Agent}
   368→		}
   369→		metadata.Agents = mergeAgents(existingAgents, opts.Agent)
   370→		// Keep Agent as the first agent for backwards compat
   371→		if len(metadata.Agents) > 0 {
   372→			metadata.Agent = metadata.Agents[0]
   373→		}
   374→
   375→		// Merge files touched (deduplicated)
   376→		metadata.FilesTouched = mergeFilesTouched(existingMetadata.FilesTouched, opts.FilesTouched)
   377→
   378→		// Sum checkpoint counts
   379→		metadata.CheckpointsCount = existingMetadata.CheckpointsCount + opts.CheckpointsCount
   380→	}
   381→
   382→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
   383→	if err != nil {
   384→		return fmt.Errorf("failed to marshal metadata: %w", err)
   385→	}
   386→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   387→	if err != nil {
   388→		return err
   389→	}
   390→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
   391→		Name: basePath + paths.MetadataFileName,
   392→		Mode: filemode.Regular,
   393→		Hash: metadataHash,
   394→	}
   395→	return nil
   396→}
   397→
   398→// mergeFilesTouched combines two file lists, removing duplicates.
   399→func mergeFilesTouched(existing, additional []string) []string {
   400→	seen := make(map[string]bool)
   401→	var result []string
   402→
   403→	for _, f := range existing {
   404→		if !seen[f] {
   405→			seen[f] = true
   406→			result = append(result, f)
   407→		}
   408→	}
   409→	for _, f := range additional {
   410→		if !seen[f] {
   411→			seen[f] = true
   412→			result = append(result, f)
   413→		}
   414→	}
   415→
   416→	sort.Strings(result)
   417→	return result
   418→}
   419→
   420→// mergeAgents combines existing agents with a new agent, removing duplicates.
   421→// Preserves order (existing agents first, then new agent if not already present).
   422→func mergeAgents(existing []agent.AgentType, newAgent agent.AgentType) []agent.AgentType {
   423→	if newAgent == "" {
   424→		return existing
   425→	}
   426→
   427→	seen := make(map[agent.AgentType]bool)
   428→	var result []agent.AgentType
   429→
   430→	for _, a := range existing {
   431→		if !seen[a] {
   432→			seen[a] = true
   433→			result = append(result, a)
   434→		}
   435→	}
   436→
   437→	if !seen[newAgent] {
   438→		result = append(result, newAgent)
   439→	}
   440→
   441→	return result
   442→}
