   465→// archiveExistingSession moves existing session files to a numbered subfolder.
   466→// The subfolder number is based on the current session count (so first archived session goes to "1/").
   467→func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
   468→	// Determine archive folder number
   469→	sessionCount := existingMetadata.SessionCount
   470→	if sessionCount == 0 {
   471→		sessionCount = 1 // backwards compat
   472→	}
   473→	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)
   474→
   475→	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
   476→	filesToArchive := []string{
   477→		paths.MetadataFileName,
   478→		paths.TranscriptFileName,
   479→		paths.PromptFileName,
   480→		paths.ContextFileName,
   481→		paths.ContentHashFileName,
   482→	}
   483→
   484→	// Also include transcript chunk files (full.jsonl.001, full.jsonl.002, etc.)
   485→	chunkPrefix := basePath + paths.TranscriptFileName + "."
   486→	for srcPath := range entries {
   487→		if strings.HasPrefix(srcPath, chunkPrefix) {
   488→			chunkSuffix := strings.TrimPrefix(srcPath, basePath+paths.TranscriptFileName)
   489→			if idx := agent.ParseChunkIndex(paths.TranscriptFileName+chunkSuffix, paths.TranscriptFileName); idx > 0 {
   490→				filesToArchive = append(filesToArchive, paths.TranscriptFileName+chunkSuffix)
   491→			}
   492→		}
   493→	}
   494→
   495→	// Move each file to archive folder
   496→	for _, filename := range filesToArchive {
   497→		srcPath := basePath + filename
   498→		if entry, exists := entries[srcPath]; exists {
   499→			// Add to archive location
   500→			dstPath := archivePath + filename
   501→			entries[dstPath] = object.TreeEntry{
   502→				Name: dstPath,
   503→				Mode: entry.Mode,
   504→				Hash: entry.Hash,
   505→			}
   506→			// Remove from original location (will be overwritten by new session)
   507→			delete(entries, srcPath)
   508→		}
   509→	}
   510→}
   511→
   512→// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
   513→// Returns sessions ordered by folder index (oldest first).
   514→func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int, agentType agent.AgentType) []ArchivedSession {
   515→	var archived []ArchivedSession
   516→
   517→	// Archived sessions are in numbered folders: 1/, 2/, etc.
   518→	// The most recent session is at the root level (not archived).
   519→	// Session count N means there are N-1 archived sessions.
   520→	for i := 1; i < sessionCount; i++ {
   521→		folderName := strconv.Itoa(i)
   522→
   523→		// Try to get the archived session subtree
   524→		subTree, err := checkpointTree.Tree(folderName)
   525→		if err != nil {
   526→			continue // Folder doesn't exist, skip
   527→		}
   528→
   529→		session := ArchivedSession{
   530→			FolderIndex: i,
   531→		}
   532→
   533→		// Read metadata to get session ID
   534→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   535→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   536→				var metadata CommittedMetadata
   537→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   538→					session.SessionID = metadata.SessionID
   539→				}
   540→			}
   541→		}
   542→
   543→		// Read transcript (handles both chunked and non-chunked formats)
   544→		if transcript, err := readTranscriptFromTree(subTree, agentType); err == nil && transcript != nil {
   545→			session.Transcript = transcript
   546→		}
   547→
   548→		// Read prompts
   549→		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
   550→			if content, contentErr := file.Contents(); contentErr == nil {
   551→				session.Prompts = content
   552→			}
   553→		}
   554→
   555→		// Only add if we got a transcript
   556→		if len(session.Transcript) > 0 {
   557→			archived = append(archived, session)
   558→		}
   559→	}
   560→
   561→	return archived
   562→}
