   748→// GetTranscript retrieves the transcript for a specific checkpoint ID.
   749→func (s *GitStore) GetTranscript(ctx context.Context, checkpointID id.CheckpointID) ([]byte, error) {
   750→	result, err := s.ReadCommitted(ctx, checkpointID)
   751→	if err != nil {
   752→		return nil, err
   753→	}
   754→	if result == nil {
   755→		return nil, fmt.Errorf("checkpoint not found: %s", checkpointID)
   756→	}
   757→	if len(result.Transcript) == 0 {
   758→		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
   759→	}
   760→	return result.Transcript, nil
   761→}
