   763→// GetSessionLog retrieves the session transcript and session ID for a checkpoint.
   764→// This is the primary method for looking up session logs by checkpoint ID.
   765→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   766→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
   767→func (s *GitStore) GetSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
   768→	result, err := s.ReadCommitted(context.Background(), cpID)
   769→	if err != nil {
   770→		return nil, "", fmt.Errorf("failed to read checkpoint: %w", err)
   771→	}
   772→	if result == nil {
   773→		return nil, "", ErrCheckpointNotFound
   774→	}
   775→	if len(result.Transcript) == 0 {
   776→		return nil, "", ErrNoTranscript
   777→	}
   778→	return result.Transcript, result.Metadata.SessionID, nil
   779→}
