   781→// LookupSessionLog is a convenience function that opens the repository and retrieves
   782→// a session log by checkpoint ID. This is the primary entry point for callers that
   783→// don't already have a GitStore instance.
   784→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   785→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
   786→func LookupSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
   787→	repo, err := git.PlainOpenWithOptions(".", &git.PlainOpenOptions{DetectDotGit: true})
   788→	if err != nil {
   789→		return nil, "", fmt.Errorf("failed to open git repository: %w", err)
   790→	}
   791→	store := NewGitStore(repo)
   792→	return store.GetSessionLog(cpID)
   793→}
