   795→// ensureSessionsBranch ensures the entire/sessions branch exists.
   796→func (s *GitStore) ensureSessionsBranch() error {
   797→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   798→	_, err := s.repo.Reference(refName, true)
   799→	if err == nil {
   800→		return nil // Branch exists
   801→	}
   802→
   803→	// Create orphan branch with empty tree
   804→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
   805→	if err != nil {
   806→		return err
   807→	}
   808→
   809→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
   810→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
   811→	if err != nil {
   812→		return err
   813→	}
   814→
   815→	newRef := plumbing.NewHashReference(refName, commitHash)
   816→	if err := s.repo.Storer.SetReference(newRef); err != nil {
   817→		return fmt.Errorf("failed to set branch reference: %w", err)
   818→	}
   819→	return nil
   820→}
