   822→// getSessionsBranchTree returns the tree object for the entire/sessions branch.
   823→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
   824→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   825→	ref, err := s.repo.Reference(refName, true)
   826→	if err != nil {
   827→		return nil, fmt.Errorf("sessions branch not found: %w", err)
   828→	}
   829→
   830→	commit, err := s.repo.CommitObject(ref.Hash())
   831→	if err != nil {
   832→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   833→	}
   834→
   835→	tree, err := commit.Tree()
   836→	if err != nil {
   837→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   838→	}
   839→
   840→	return tree, nil
   841→}
