   843→// CreateBlobFromContent creates a blob object from in-memory content.
   844→// Exported for use by strategy package (session_test.go)
   845→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
   846→	obj := repo.Storer.NewEncodedObject()
   847→	obj.SetType(plumbing.BlobObject)
   848→	obj.SetSize(int64(len(content)))
   849→
   850→	writer, err := obj.Writer()
   851→	if err != nil {
   852→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
   853→	}
   854→
   855→	_, err = writer.Write(content)
   856→	if err != nil {
   857→		_ = writer.Close()
   858→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
   859→	}
   860→	if err := writer.Close(); err != nil {
   861→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
   862→	}
   863→
   864→	hash, err := repo.Storer.SetEncodedObject(obj)
   865→	if err != nil {
   866→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
   867→	}
   868→	return hash, nil
   869→}
