   871→// copyMetadataDir copies all files from a directory to the checkpoint path.
   872→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
   873→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
   874→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
   875→		if err != nil {
   876→			return err
   877→		}
   878→		if info.IsDir() {
   879→			return nil
   880→		}
   881→
   882→		// Skip symlinks to prevent reading files outside the metadata directory.
   883→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
   884→		// then be captured in the checkpoint and stored in git history.
   885→		if info.Mode()&os.ModeSymlink != 0 {
   886→			return nil
   887→		}
   888→
   889→		// Get relative path within metadata dir
   890→		relPath, err := filepath.Rel(metadataDir, path)
   891→		if err != nil {
   892→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
   893→		}
   894→
   895→		// Prevent path traversal via symlinks pointing outside the metadata dir
   896→		if strings.HasPrefix(relPath, "..") {
   897→			return fmt.Errorf("path traversal detected: %s", relPath)
   898→		}
   899→
   900→		// Create blob from file
   901→		blobHash, mode, err := createBlobFromFile(s.repo, path)
   902→		if err != nil {
   903→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
   904→		}
   905→
   906→		// Store at checkpoint path
   907→		fullPath := basePath + relPath
   908→		entries[fullPath] = object.TreeEntry{
   909→			Name: fullPath,
   910→			Mode: mode,
   911→			Hash: blobHash,
   912→		}
   913→
   914→		return nil
   915→	})
   916→	if err != nil {
