   942→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
   943→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
   944→// The agentType is used for reassembling chunks in the correct format.
   945→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
   946→	// Collect all transcript-related files
   947→	var chunkFiles []string
   948→	var hasBaseFile bool
   949→
   950→	for _, entry := range tree.Entries {
   951→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
   952→			hasBaseFile = true
   953→		}
   954→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
   955→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
   956→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
   957→			if idx > 0 {
   958→				chunkFiles = append(chunkFiles, entry.Name)
   959→			}
   960→		}
   961→	}
   962→
   963→	// If we have chunk files, read and reassemble them
   964→	if len(chunkFiles) > 0 {
   965→		// Sort chunk files by index
   966→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
   967→
   968→		// Check if base file should be included as chunk 0.
   969→		// NOTE: This assumes the chunking convention where the unsuffixed file
   970→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
   971→		if hasBaseFile {
   972→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
   973→		}
   974→
   975→		var chunks [][]byte
   976→		for _, chunkFile := range chunkFiles {
   977→			file, err := tree.File(chunkFile)
   978→			if err != nil {
   979→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
   980→					slog.String("chunk_file", chunkFile),
   981→					slog.String("error", err.Error()),
   982→				)
   983→				continue
   984→			}
   985→			content, err := file.Contents()
   986→			if err != nil {
   987→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
   988→					slog.String("chunk_file", chunkFile),
   989→					slog.String("error", err.Error()),
   990→				)
   991→				continue
   992→			}
   993→			chunks = append(chunks, []byte(content))
   994→		}
   995→
   996→		if len(chunks) > 0 {
   997→			result, err := agent.ReassembleTranscript(chunks, agentType)
   998→			if err != nil {
   999→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1000→			}
  1001→			return result, nil
  1002→		}
  1003→	}
  1004→
  1005→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1006→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1007→		if content, err := file.Contents(); err == nil {
  1008→			return []byte(content), nil
  1009→		}
  1010→	}
  1011→
  1012→	// Try legacy filename
  1013→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1014→		if content, err := file.Contents(); err == nil {
  1015→			return []byte(content), nil
  1016→		}
  1017→	}
  1018→
  1019→	return nil, nil
  1020→}
