   677→// determineSettingsTarget decides whether to write to settings.local.json based on:
   678→// - Whether settings.json already exists
   679→// - The --local and --project flags
   680→// Returns (useLocal, showNotification).
   681→func determineSettingsTarget(entireDir string, useLocal, useProject bool) (bool, bool) {
   682→	// Explicit --local flag always uses local settings
   683→	if useLocal {
   684→		return true, false
   685→	}
   686→
   687→	// Explicit --project flag always uses project settings
   688→	if useProject {
   689→		return false, false
   690→	}
   691→
   692→	// No flags specified - check if settings file exists
   693→	settingsPath := filepath.Join(entireDir, paths.SettingsFileName)
   694→	if _, err := os.Stat(settingsPath); err == nil {
   695→		// Settings file exists - auto-redirect to local with notification
   696→		return true, true
   697→	}
   698→
   699→	// Settings file doesn't exist - create it
   700→	return false, false
   701→}
