   148→// PromptResponsePair represents a user prompt and the assistant's responses.
   149→// Used for extracting all interactions from a transcript.
   150→type PromptResponsePair struct {
   151→	Prompt    string
   152→	Responses []string // Multiple responses can occur between tool calls
   153→	Files     []string
   154→}
   155→
   156→// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
   157→// Returns pairs in chronological order (oldest first).
   158→// Each pair contains the user's prompt, assistant's text response, and files modified.
   159→func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
   160→	var pairs []PromptResponsePair
   161→
   162→	// Find all user prompts (messages with string content, not tool results)
   163→	var userIndices []int
   164→	for i, line := range transcript {
   165→		if line.Type == transcriptTypeUser {
   166→			var msg userMessage
   167→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   168→				continue
   169→			}
   170→			// Only count messages with string content (real user prompts)
   171→			if _, ok := msg.Content.(string); ok {
   172→				userIndices = append(userIndices, i)
   173→			} else if arr, ok := msg.Content.([]interface{}); ok {
   174→				// Check if array has text blocks (also a real user prompt)
   175→				for _, item := range arr {
   176→					if m, ok := item.(map[string]interface{}); ok {
   177→						if m["type"] == contentTypeText {
   178→							userIndices = append(userIndices, i)
   179→							break
   180→						}
   181→					}
   182→				}
   183→			}
   184→		}
   185→	}
   186→
   187→	// For each user prompt, extract the prompt text, following assistant response, and files
   188→	for idx, userIdx := range userIndices {
   189→		// Determine the range for this prompt's conversation
   190→		endIdx := len(transcript)
   191→		if idx < len(userIndices)-1 {
   192→			endIdx = userIndices[idx+1]
   193→		}
   194→
   195→		// Extract prompt text
   196→		prompt := extractUserPromptAt(transcript, userIdx)
   197→		if prompt == "" {
   198→			continue
   199→		}
   200→
   201→		// Extract assistant responses and files from this range
   202→		slice := transcript[userIdx:endIdx]
   203→		responses := extractAssistantResponses(slice)
   204→		files := extractModifiedFiles(slice)
   205→
   206→		pairs = append(pairs, PromptResponsePair{
   207→			Prompt:    prompt,
   208→			Responses: responses,
   209→			Files:     files,
   210→		})
   211→	}
   212→
   213→	return pairs
   214→}
