   253→// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
   254→// A single prompt can trigger multiple assistant responses interspersed with tool calls.
   255→func extractAssistantResponses(transcript []transcriptLine) []string {
   256→	var texts []string
   257→	for _, line := range transcript {
   258→		if line.Type == transcriptTypeAssistant {
   259→			var msg assistantMessage
   260→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   261→				continue
   262→			}
   263→
   264→			for _, block := range msg.Content {
   265→				if block.Type == contentTypeText && block.Text != "" {
   266→					texts = append(texts, block.Text)
   267→				}
   268→			}
   269→		}
   270→	}
   271→	return texts
   272→}
