   278→	var prompts []string
   279→	for i := range transcript {
   280→		if transcript[i].Type != transcriptTypeUser {
   281→			continue
   282→		}
   283→		var msg userMessage
   284→		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   285→			continue
   286→		}
   287→
   288→		// Handle string content
   289→		if str, ok := msg.Content.(string); ok {
   290→			prompts = append(prompts, textutil.StripIDEContextTags(str))
   291→			continue
   292→		}
   293→
   294→		// Handle array content (only if it contains text blocks)
   295→		if arr, ok := msg.Content.([]interface{}); ok {
   296→			var texts []string
   297→			for _, item := range arr {
   298→				if m, ok := item.(map[string]interface{}); ok {
   299→					if m["type"] == contentTypeText {
   300→						if text, ok := m["text"].(string); ok {
   301→							texts = append(texts, text)
   302→						}
   303→					}
   304→				}
   305→			}
