   507→// verifyBranchInMetadata reads and verifies the branch field in metadata.json.
   508→func verifyBranchInMetadata(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID, expectedBranch string, shouldOmit bool) {
   509→	t.Helper()
   510→
   511→	metadataRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
   512→	if err != nil {
   513→		t.Fatalf("failed to get metadata branch reference: %v", err)
   514→	}
   515→
   516→	commit, err := repo.CommitObject(metadataRef.Hash())
   517→	if err != nil {
   518→		t.Fatalf("failed to get commit object: %v", err)
   519→	}
   520→
   521→	tree, err := commit.Tree()
   522→	if err != nil {
   523→		t.Fatalf("failed to get tree: %v", err)
   524→	}
   525→
   526→	shardedPath := checkpointID.Path()
   527→	metadataPath := shardedPath + "/" + paths.MetadataFileName
   528→	metadataFile, err := tree.File(metadataPath)
   529→	if err != nil {
   530→		t.Fatalf("failed to find metadata.json at %s: %v", metadataPath, err)
   531→	}
   532→
   533→	content, err := metadataFile.Contents()
   534→	if err != nil {
   535→		t.Fatalf("failed to read metadata.json: %v", err)
   536→	}
   537→
   538→	var metadata CommittedMetadata
   539→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
   540→		t.Fatalf("failed to parse metadata.json: %v", err)
   541→	}
   542→
   543→	if metadata.Branch != expectedBranch {
   544→		t.Errorf("metadata.Branch = %q, want %q", metadata.Branch, expectedBranch)
   545→	}
   546→
   547→	if shouldOmit && strings.Contains(content, `"branch"`) {
   548→		t.Errorf("metadata.json should not contain 'branch' field when empty (omitempty), got:\n%s", content)
   549→	}
   550→}
