   236→// generateCheckpointSummary generates an AI summary for a checkpoint and persists it.
   237→func generateCheckpointSummary(w, errW io.Writer, store *checkpoint.GitStore, checkpointID id.CheckpointID, result *checkpoint.ReadCommittedResult, force bool) error {
   238→	// Check if summary already exists
   239→	if result.Metadata.Summary != nil && !force {
   240→		return fmt.Errorf("checkpoint %s already has a summary (use --force to regenerate)", checkpointID.String()[:checkpointIDDisplayLength])
   241→	}
   242→
   243→	// Check if transcript exists
   244→	if len(result.Transcript) == 0 {
   245→		return fmt.Errorf("checkpoint %s has no transcript to summarize", checkpointID.String()[:checkpointIDDisplayLength])
   246→	}
   247→
   248→	// Parse the transcript
   249→	transcript, err := parseTranscriptFromBytes(result.Transcript)
   250→	if err != nil {
   251→		return fmt.Errorf("failed to parse transcript: %w", err)
   252→	}
   253→
   254→	// Build condensed transcript for summarization
   255→	condensed := BuildCondensedTranscript(transcript)
   256→	if len(condensed) == 0 {
   257→		return fmt.Errorf("checkpoint %s transcript has no content to summarize", checkpointID.String()[:checkpointIDDisplayLength])
   258→	}
   259→
   260→	input := SummaryInput{
   261→		Transcript:   condensed,
   262→		FilesTouched: result.Metadata.FilesTouched,
   263→	}
   264→
   265→	// Show progress indicator
   266→	fmt.Fprintln(errW, "Generating summary...")
   267→
   268→	// Generate summary using Claude CLI
   269→	generator := &ClaudeCLIGenerator{}
   270→	ctx := context.Background()
   271→	summary, err := generator.Generate(ctx, input)
   272→	if err != nil {
   273→		return fmt.Errorf("failed to generate summary: %w", err)
   274→	}
   275→
   276→	// Persist the summary
   277→	if err := store.UpdateSummary(ctx, checkpointID, summary); err != nil {
   278→		return fmt.Errorf("failed to save summary: %w", err)
   279→	}
   280→
   281→	fmt.Fprintln(w, "Summary generated and saved.")
   282→	return nil
   283→}
