   285→// explainTemporaryCheckpoint finds and formats a temporary checkpoint by shadow commit hash prefix.
   286→// Returns the formatted output and whether the checkpoint was found.
   287→func explainTemporaryCheckpoint(repo *git.Repository, store *checkpoint.GitStore, shaPrefix string, verbose, full bool) (string, bool) {
   288→	// Get current HEAD to find shadow branch
   289→	head, err := repo.Head()
   290→	if err != nil {
   291→		return "", false
   292→	}
   293→	headShort := head.Hash().String()[:7]
   294→
   295→	// List temporary checkpoints on current shadow branch
   296→	tempCheckpoints, err := store.ListTemporaryCheckpoints(context.Background(), headShort, "", branchCheckpointsLimit)
   297→	if err != nil {
   298→		return "", false
   299→	}
   300→
   301→	// Find checkpoint matching the SHA prefix - check for ambiguity
   302→	var matchIdx = -1
   303→	for i, tc := range tempCheckpoints {
   304→		if strings.HasPrefix(tc.CommitHash.String(), shaPrefix) {
   305→			if matchIdx >= 0 {
   306→				// Multiple matches - ambiguous prefix
   307→				return "", false
   308→			}
   309→			matchIdx = i
   310→		}
   311→	}
   312→
   313→	if matchIdx < 0 {
   314→		return "", false
   315→	}
   316→
   317→	tc := tempCheckpoints[matchIdx]
   318→
   319→	// Found exactly one match - read metadata from shadow branch commit tree
   320→	shadowCommit, commitErr := repo.CommitObject(tc.CommitHash)
   321→	if commitErr != nil {
   322→		return "", false
   323→	}
   324→
   325→	shadowTree, treeErr := shadowCommit.Tree()
   326→	if treeErr != nil {
   327→		return "", false
   328→	}
   329→
   330→	// Read prompts from shadow branch
   331→	sessionPrompt := strategy.ReadSessionPromptFromTree(shadowTree, tc.MetadataDir)
   332→
   333→	// Build output similar to formatCheckpointOutput but for temporary
   334→	var sb strings.Builder
   335→	shortID := tc.CommitHash.String()[:7]
   336→	fmt.Fprintf(&sb, "Checkpoint: %s [temporary]\n", shortID)
   337→	fmt.Fprintf(&sb, "Session: %s\n", tc.SessionID)
   338→	fmt.Fprintf(&sb, "Created: %s\n", tc.Timestamp.Format("2006-01-02 15:04:05"))
   339→	sb.WriteString("\n")
   340→
   341→	// Intent from prompt
   342→	intent := "(not available)"
   343→	if sessionPrompt != "" {
   344→		lines := strings.Split(sessionPrompt, "\n")
   345→		if len(lines) > 0 && lines[0] != "" {
   346→			intent = strategy.TruncateDescription(lines[0], maxIntentDisplayLength)
   347→		}
   348→	}
   349→	fmt.Fprintf(&sb, "Intent: %s\n", intent)
   350→	sb.WriteString("Outcome: (not generated)\n")
   351→
   352→	// Verbose: show prompts
   353→	if verbose || full {
   354→		sb.WriteString("\n")
   355→		sb.WriteString("Prompts:\n")
   356→		if sessionPrompt != "" {
   357→			sb.WriteString(sessionPrompt)
   358→			sb.WriteString("\n")
   359→		} else {
   360→			sb.WriteString("  (none)\n")
   361→		}
   362→	}
   363→
   364→	// Full: show transcript
   365→	if full {
   366→		// Try to read transcript from shadow branch
   367→		transcriptPath := tc.MetadataDir + "/full.jsonl"
   368→		if transcriptFile, fileErr := shadowTree.File(transcriptPath); fileErr == nil {
   369→			if content, readErr := transcriptFile.Contents(); readErr == nil {
   370→				sb.WriteString("\n")
   371→				sb.WriteString("Transcript:\n")
   372→				sb.WriteString(content)
   373→				sb.WriteString("\n")
   374→			}
   375→		}
   376→	}
   377→
   378→	return sb.String(), true
   379→}
