   519→// formatSummaryDetails formats the detailed sections of an AI summary.
   520→func formatSummaryDetails(sb *strings.Builder, summary *checkpoint.Summary) {
   521→	// Learnings section
   522→	hasLearnings := len(summary.Learnings.Repo) > 0 ||
   523→		len(summary.Learnings.Code) > 0 ||
   524→		len(summary.Learnings.Workflow) > 0
   525→
   526→	if hasLearnings {
   527→		sb.WriteString("\nLearnings:\n")
   528→
   529→		if len(summary.Learnings.Repo) > 0 {
   530→			sb.WriteString("  Repository:\n")
   531→			for _, learning := range summary.Learnings.Repo {
   532→				fmt.Fprintf(sb, "    - %s\n", learning)
   533→			}
   534→		}
   535→
   536→		if len(summary.Learnings.Code) > 0 {
   537→			sb.WriteString("  Code:\n")
   538→			for _, learning := range summary.Learnings.Code {
   539→				if learning.Line > 0 {
   540→					if learning.EndLine > 0 {
   541→						fmt.Fprintf(sb, "    - %s:%d-%d: %s\n", learning.Path, learning.Line, learning.EndLine, learning.Finding)
   542→					} else {
   543→						fmt.Fprintf(sb, "    - %s:%d: %s\n", learning.Path, learning.Line, learning.Finding)
   544→					}
   545→				} else {
   546→					fmt.Fprintf(sb, "    - %s: %s\n", learning.Path, learning.Finding)
   547→				}
   548→			}
   549→		}
   550→
   551→		if len(summary.Learnings.Workflow) > 0 {
   552→			sb.WriteString("  Workflow:\n")
   553→			for _, learning := range summary.Learnings.Workflow {
   554→				fmt.Fprintf(sb, "    - %s\n", learning)
   555→			}
   556→		}
   557→	}
   558→
   559→	// Friction section
   560→	if len(summary.Friction) > 0 {
   561→		sb.WriteString("\nFriction:\n")
   562→		for _, item := range summary.Friction {
   563→			fmt.Fprintf(sb, "  - %s\n", item)
   564→		}
   565→	}
   566→
   567→	// Open items section
   568→	if len(summary.OpenItems) > 0 {
   569→		sb.WriteString("\nOpen Items:\n")
   570→		for _, item := range summary.OpenItems {
   571→			fmt.Fprintf(sb, "  - %s\n", item)
   572→		}
   573→	}
   574→}
