   782→// runExplainBranchDefault shows all checkpoints on the current branch grouped by date.
   783→// This is strategy-agnostic - it queries checkpoints directly.
   784→func runExplainBranchDefault(w io.Writer, noPager bool) error {
   785→	repo, err := openRepository()
   786→	if err != nil {
   787→		return fmt.Errorf("not a git repository: %w", err)
   788→	}
   789→
   790→	// Get current branch name
   791→	branchName := strategy.GetCurrentBranchName(repo)
   792→	if branchName == "" {
   793→		// Detached HEAD state - use short commit hash instead
   794→		head, headErr := repo.Head()
   795→		if headErr != nil {
   796→			return fmt.Errorf("failed to get HEAD: %w", headErr)
   797→		}
   798→		branchName = "HEAD (" + head.Hash().String()[:7] + ")"
   799→	}
   800→
   801→	// Get checkpoints for this branch (strategy-agnostic)
   802→	points, err := getBranchCheckpoints(repo, branchCheckpointsLimit)
   803→	if err != nil {
   804→		points = nil // Continue with empty list on error
   805→	}
   806→
   807→	// Format output
   808→	output := formatBranchCheckpoints(branchName, points)
   809→
   810→	outputExplainContent(w, output, noPager)
   811→	return nil
   812→}
