   823→// runExplainSession explains a specific session.
   824→func runExplainSession(w io.Writer, sessionID string, noPager bool) error {
   825→	strat := GetStrategy()
   826→
   827→	// Get session details
   828→	session, err := strategy.GetSession(sessionID)
   829→	if err != nil {
   830→		if errors.Is(err, strategy.ErrNoSession) {
   831→			return fmt.Errorf("session not found: %s", sessionID)
   832→		}
   833→		return fmt.Errorf("failed to get session: %w", err)
   834→	}
   835→
   836→	// Get source ref (metadata branch + commit) for this session
   837→	sourceRef := strat.GetSessionMetadataRef(session.ID)
   838→
   839→	// Gather checkpoint details
   840→	checkpointDetails := gatherCheckpointDetails(strat, session)
   841→
   842→	// For strategies like shadow where active sessions may not have checkpoints,
   843→	// try to get the current session transcript directly
   844→	if len(checkpointDetails) == 0 && len(session.Checkpoints) == 0 {
   845→		checkpointDetails = gatherCurrentSessionDetails(strat, session)
   846→	}
   847→
   848→	// Format output
   849→	output := formatSessionInfo(session, sourceRef, checkpointDetails)
   850→
   851→	// Output with pager if appropriate
   852→	if noPager {
   853→		fmt.Fprint(w, output)
   854→	} else {
   855→		outputWithPager(w, output)
   856→	}
   857→
   858→	return nil
   859→}
