   861→// gatherCurrentSessionDetails attempts to get transcript info for sessions without checkpoints.
   862→// This handles strategies like shadow where active sessions may not have checkpoint commits.
   863→func gatherCurrentSessionDetails(strat strategy.Strategy, session *strategy.Session) []checkpointDetail {
   864→	// Try to get transcript via GetSessionContext which reads from metadata branch
   865→	// For shadow, we can read the transcript from the same location pattern
   866→	contextContent := strat.GetSessionContext(session.ID)
   867→	if contextContent == "" {
   868→		return nil
   869→	}
   870→
   871→	// Parse the context.md to extract the last prompt/summary
   872→	// Context.md typically has sections like "# Prompt\n...\n## Summary\n..."
   873→	detail := checkpointDetail{
   874→		Index:     1,
   875→		Timestamp: session.StartTime,
   876→		Message:   "Current session",
   877→	}
   878→
   879→	// Try to extract prompt and summary from context.md
   880→	lines := strings.Split(contextContent, "\n")
   881→	var inPrompt, inSummary bool
   882→	var promptLines, summaryLines []string
   883→
   884→	for _, line := range lines {
   885→		trimmed := strings.TrimSpace(line)
   886→		if strings.HasPrefix(trimmed, "# ") && strings.Contains(strings.ToLower(trimmed), "prompt") {
   887→			inPrompt = true
   888→			inSummary = false
   889→			continue
   890→		}
   891→		if strings.HasPrefix(trimmed, "## ") && strings.Contains(strings.ToLower(trimmed), "summary") {
   892→			inPrompt = false
   893→			inSummary = true
   894→			continue
   895→		}
   896→		if strings.HasPrefix(trimmed, "## ") || strings.HasPrefix(trimmed, "# ") {
   897→			inPrompt = false
   898→			inSummary = false
   899→			continue
   900→		}
   901→
   902→		if inPrompt {
   903→			promptLines = append(promptLines, line)
   904→		} else if inSummary {
   905→			summaryLines = append(summaryLines, line)
   906→		}
   907→	}
   908→
   909→	var inter interaction
   910→	if len(promptLines) > 0 {
   911→		inter.Prompt = strings.TrimSpace(strings.Join(promptLines, "\n"))
   912→	}
   913→	if len(summaryLines) > 0 {
   914→		inter.Responses = []string{strings.TrimSpace(strings.Join(summaryLines, "\n"))}
   915→	}
   916→
   917→	// If we couldn't parse structured content, show the raw context
   918→	if inter.Prompt == "" && len(inter.Responses) == 0 {
   919→		inter.Responses = []string{contextContent}
   920→	}
   921→
   922→	if inter.Prompt != "" || len(inter.Responses) > 0 {
   923→		detail.Interactions = []interaction{inter}
   924→	}
   925→
   926→	return []checkpointDetail{detail}
   927→}
   928→
   929→// gatherCheckpointDetails extracts detailed information for each checkpoint.
   930→// Checkpoints come in newest-first order, but we number them oldest=1, newest=N.
   931→func gatherCheckpointDetails(strat strategy.Strategy, session *strategy.Session) []checkpointDetail {
   932→	details := make([]checkpointDetail, 0, len(session.Checkpoints))
   933→	total := len(session.Checkpoints)
   934→
   935→	for i, cp := range session.Checkpoints {
   936→		detail := checkpointDetail{
   937→			Index:            total - i, // Reverse numbering: oldest=1, newest=N
   938→			Timestamp:        cp.Timestamp,
   939→			IsTaskCheckpoint: cp.IsTaskCheckpoint,
   940→			Message:          cp.Message,
   941→		}
   942→
   943→		// Use checkpoint ID for display (truncate long IDs)
   944→		detail.ShortID = cp.CheckpointID.String()
   945→		if len(detail.ShortID) > 12 {
   946→			detail.ShortID = detail.ShortID[:12]
   947→		}
   948→
   949→		// Try to get transcript for this checkpoint
   950→		transcriptContent, err := strat.GetCheckpointLog(cp)
   951→		if err == nil {
   952→			transcript, parseErr := parseTranscriptFromBytes(transcriptContent)
   953→			if parseErr == nil {
   954→				// Extract all prompt/response pairs from the transcript
   955→				pairs := ExtractAllPromptResponses(transcript)
   956→				for _, pair := range pairs {
   957→					detail.Interactions = append(detail.Interactions, interaction(pair))
   958→				}
   959→
   960→				// Aggregate all files for the checkpoint
   961→				fileSet := make(map[string]bool)
   962→				for _, pair := range pairs {
   963→					for _, f := range pair.Files {
   964→						if !fileSet[f] {
   965→							fileSet[f] = true
   966→							detail.Files = append(detail.Files, f)
   967→						}
   968→					}
   969→				}
   970→			}
   971→		}
   972→
   973→		details = append(details, detail)
   974→	}
   975→
   976→	return details
   977→}
   978→
   979→// runExplainCommit explains a specific commit.
   980→func runExplainCommit(w io.Writer, commitRef string) error {
   981→	repo, err := openRepository()
   982→	if err != nil {
   983→		return fmt.Errorf("not a git repository: %w", err)
   984→	}
   985→
   986→	// Resolve the commit reference
   987→	hash, err := repo.ResolveRevision(plumbing.Revision(commitRef))
   988→	if err != nil {
   989→		return fmt.Errorf("commit not found: %s", commitRef)
   990→	}
   991→
   992→	commit, err := repo.CommitObject(*hash)
   993→	if err != nil {
   994→		return fmt.Errorf("failed to get commit: %w", err)
   995→	}
   996→
   997→	// Get files changed in this commit (diff from parent to current)
   998→	var files []string
   999→	commitTree, err := commit.Tree()
  1000→	if err == nil && commit.NumParents() > 0 {
  1001→		parent, parentErr := commit.Parent(0)
  1002→		if parentErr == nil {
  1003→			parentTree, treeErr := parent.Tree()
  1004→			if treeErr == nil {
  1005→				// Diff from parent to current commit to show what changed
  1006→				changes, diffErr := parentTree.Diff(commitTree)
  1007→				if diffErr == nil {
  1008→					for _, change := range changes {
  1009→						name := change.To.Name
  1010→						if name == "" {
  1011→							name = change.From.Name
  1012→						}
  1013→						files = append(files, name)
  1014→					}
  1015→				}
  1016→			}
  1017→		}
  1018→	}
  1019→
  1020→	// Check for Entire metadata - try multiple trailer types
  1021→	metadataDir, hasMetadata := trailers.ParseMetadata(commit.Message)
  1022→	sessionID, hasSession := trailers.ParseSession(commit.Message)
  1023→	checkpointID, hasCheckpoint := trailers.ParseCheckpoint(commit.Message)
  1024→
  1025→	// If no session trailer, try to extract from metadata path.
  1026→	// Note: extractSessionIDFromMetadata is defined in rewind.go as it's used
  1027→	// by both the rewind and explain commands for parsing metadata paths.
  1028→	if !hasSession && hasMetadata {
  1029→		sessionID = extractSessionIDFromMetadata(metadataDir)
  1030→		hasSession = sessionID != ""
  1031→	}
  1032→
  1033→	// Build commit info
  1034→	fullSHA := hash.String()
  1035→	shortSHA := fullSHA
  1036→	if len(fullSHA) >= 7 {
  1037→		shortSHA = fullSHA[:7]
  1038→	}
  1039→
  1040→	info := &commitInfo{
  1041→		SHA:       fullSHA,
  1042→		ShortSHA:  shortSHA,
  1043→		Message:   strings.Split(commit.Message, "\n")[0], // First line only
  1044→		Author:    commit.Author.Name,
  1045→		Email:     commit.Author.Email,
  1046→		Date:      commit.Author.When,
  1047→		Files:     files,
  1048→		HasEntire: hasMetadata || hasSession || hasCheckpoint,
  1049→		SessionID: sessionID,
  1050→	}
  1051→
  1052→	// If we have a checkpoint ID but no session, try to look up session from metadata
  1053→	if hasCheckpoint && sessionID == "" {
  1054→		if result, err := checkpoint.NewGitStore(repo).ReadCommitted(context.Background(), checkpointID); err == nil && result != nil {
  1055→			info.SessionID = result.Metadata.SessionID
  1056→		}
  1057→	}
  1058→
  1059→	// Format and output
  1060→	output := formatCommitInfo(info)
  1061→	fmt.Fprint(w, output)
  1062→
  1063→	return nil
  1064→}
