  1066→// formatSessionInfo formats session information for display.
  1067→func formatSessionInfo(session *strategy.Session, sourceRef string, checkpoints []checkpointDetail) string {
  1068→	var sb strings.Builder
  1069→
  1070→	// Session header
  1071→	fmt.Fprintf(&sb, "Session: %s\n", session.ID)
  1072→	fmt.Fprintf(&sb, "Strategy: %s\n", session.Strategy)
  1073→
  1074→	if !session.StartTime.IsZero() {
  1075→		fmt.Fprintf(&sb, "Started: %s\n", session.StartTime.Format("2006-01-02 15:04:05"))
  1076→	}
  1077→
  1078→	if sourceRef != "" {
  1079→		fmt.Fprintf(&sb, "Source Ref: %s\n", sourceRef)
  1080→	}
  1081→
  1082→	fmt.Fprintf(&sb, "Checkpoints: %d\n", len(checkpoints))
  1083→
  1084→	// Checkpoint details
  1085→	for _, cp := range checkpoints {
  1086→		sb.WriteString("\n")
  1087→
  1088→		// Checkpoint header
  1089→		taskMarker := ""
  1090→		if cp.IsTaskCheckpoint {
  1091→			taskMarker = " [Task]"
  1092→		}
  1093→		fmt.Fprintf(&sb, "─── Checkpoint %d [%s] %s%s ───\n",
  1094→			cp.Index, cp.ShortID, cp.Timestamp.Format("2006-01-02 15:04"), taskMarker)
  1095→		sb.WriteString("\n")
  1096→
  1097→		// Display all interactions in this checkpoint
  1098→		for i, inter := range cp.Interactions {
  1099→			// For multiple interactions, add a sub-header
  1100→			if len(cp.Interactions) > 1 {
  1101→				fmt.Fprintf(&sb, "### Interaction %d\n\n", i+1)
  1102→			}
  1103→
  1104→			// Prompt section
  1105→			if inter.Prompt != "" {
  1106→				sb.WriteString("## Prompt\n\n")
  1107→				sb.WriteString(inter.Prompt)
  1108→				sb.WriteString("\n\n")
  1109→			}
  1110→
  1111→			// Response section
  1112→			if len(inter.Responses) > 0 {
  1113→				sb.WriteString("## Responses\n\n")
  1114→				sb.WriteString(strings.Join(inter.Responses, "\n\n"))
  1115→				sb.WriteString("\n\n")
  1116→			}
  1117→
  1118→			// Files modified for this interaction
  1119→			if len(inter.Files) > 0 {
  1120→				fmt.Fprintf(&sb, "Files Modified (%d):\n", len(inter.Files))
  1121→				for _, file := range inter.Files {
  1122→					fmt.Fprintf(&sb, "  - %s\n", file)
  1123→				}
  1124→				sb.WriteString("\n")
  1125→			}
  1126→		}
  1127→
  1128→		// If no interactions, show message and/or files
  1129→		if len(cp.Interactions) == 0 {
  1130→			// Show commit message as summary when no transcript available
  1131→			if cp.Message != "" {
  1132→				sb.WriteString(cp.Message)
  1133→				sb.WriteString("\n\n")
  1134→			}
  1135→			// Show aggregate files if available
  1136→			if len(cp.Files) > 0 {
  1137→				fmt.Fprintf(&sb, "Files Modified (%d):\n", len(cp.Files))
  1138→				for _, file := range cp.Files {
  1139→					fmt.Fprintf(&sb, "  - %s\n", file)
  1140→				}
  1141→			}
  1142→		}
  1143→	}
  1144→
  1145→	return sb.String()
  1146→}
