  1232→// formatBranchCheckpoints formats checkpoint information for a branch.
  1233→// Groups commits by checkpoint ID and shows the prompt for each checkpoint.
  1234→func formatBranchCheckpoints(branchName string, points []strategy.RewindPoint) string {
  1235→	var sb strings.Builder
  1236→
  1237→	// Branch header
  1238→	fmt.Fprintf(&sb, "Branch: %s\n", branchName)
  1239→
  1240→	if len(points) == 0 {
  1241→		sb.WriteString("Checkpoints: 0\n")
  1242→		sb.WriteString("\nNo checkpoints found on this branch.\n")
  1243→		sb.WriteString("Checkpoints will appear here after you save changes during a Claude session.\n")
  1244→		return sb.String()
  1245→	}
  1246→
  1247→	// Group by checkpoint ID
  1248→	groups := groupByCheckpointID(points)
  1249→
  1250→	fmt.Fprintf(&sb, "Checkpoints: %d\n", len(groups))
  1251→	sb.WriteString("\n")
  1252→
  1253→	// Output each checkpoint group
  1254→	for _, group := range groups {
  1255→		formatCheckpointGroup(&sb, group)
  1256→		sb.WriteString("\n")
  1257→	}
  1258→
  1259→	return sb.String()
  1260→}
