  1262→// checkpointGroup represents a group of commits sharing the same checkpoint ID.
  1263→type checkpointGroup struct {
  1264→	checkpointID string
  1265→	prompt       string
  1266→	isTemporary  bool // true if any commit is not logs-only (can be rewound)
  1267→	isTask       bool // true if this is a task checkpoint
  1268→	commits      []commitEntry
  1269→}
  1270→
  1271→// commitEntry represents a single git commit within a checkpoint.
  1272→type commitEntry struct {
  1273→	date    time.Time
  1274→	gitSHA  string // short git SHA
  1275→	message string
  1276→}
  1277→
  1278→// groupByCheckpointID groups rewind points by their checkpoint ID.
  1279→// Returns groups sorted by latest commit timestamp (most recent first).
  1280→func groupByCheckpointID(points []strategy.RewindPoint) []checkpointGroup {
  1281→	if len(points) == 0 {
  1282→		return nil
  1283→	}
  1284→
  1285→	// Build map of checkpoint ID -> group
  1286→	groupMap := make(map[string]*checkpointGroup)
  1287→	var order []string // Track insertion order for stable iteration
  1288→
  1289→	for _, point := range points {
  1290→		// Determine the checkpoint ID to use
  1291→		cpID := point.CheckpointID.String()
  1292→		if cpID == "" {
  1293→			// All temporary checkpoints group together under "temporary"
  1294→			cpID = "temporary"
  1295→		}
  1296→
  1297→		group, exists := groupMap[cpID]
  1298→		if !exists {
  1299→			group = &checkpointGroup{
  1300→				checkpointID: cpID,
  1301→				prompt:       point.SessionPrompt,
  1302→				isTemporary:  !point.IsLogsOnly,
  1303→				isTask:       point.IsTaskCheckpoint,
  1304→			}
  1305→			groupMap[cpID] = group
  1306→			order = append(order, cpID)
  1307→		}
  1308→
  1309→		// Short git SHA (7 chars)
  1310→		gitSHA := point.ID
  1311→		if len(gitSHA) > 7 {
  1312→			gitSHA = gitSHA[:7]
  1313→		}
  1314→
  1315→		group.commits = append(group.commits, commitEntry{
  1316→			date:    point.Date,
  1317→			gitSHA:  gitSHA,
  1318→			message: point.Message,
  1319→		})
  1320→
  1321→		// Update flags - if any commit is temporary/task, the group is too
  1322→		if !point.IsLogsOnly {
  1323→			group.isTemporary = true
  1324→		}
  1325→		if point.IsTaskCheckpoint {
  1326→			group.isTask = true
  1327→		}
  1328→	}
  1329→
  1330→	// Sort commits within each group by date (most recent first)
  1331→	for _, group := range groupMap {
  1332→		sort.Slice(group.commits, func(i, j int) bool {
  1333→			return group.commits[i].date.After(group.commits[j].date)
  1334→		})
  1335→	}
  1336→
  1337→	// Build result slice in order, then sort by latest commit
  1338→	result := make([]checkpointGroup, 0, len(order))
  1339→	for _, cpID := range order {
  1340→		result = append(result, *groupMap[cpID])
  1341→	}
  1342→
  1343→	// Sort groups by latest commit timestamp (most recent first)
  1344→	sort.Slice(result, func(i, j int) bool {
  1345→		// Each group's commits are already sorted, so first commit is latest
  1346→		if len(result[i].commits) == 0 {
  1347→			return false
  1348→		}
  1349→		if len(result[j].commits) == 0 {
  1350→			return true
  1351→		}
  1352→		return result[i].commits[0].date.After(result[j].commits[0].date)
  1353→	})
  1354→
  1355→	return result
  1356→}
