  1358→// formatCheckpointGroup formats a single checkpoint group for display.
  1359→func formatCheckpointGroup(sb *strings.Builder, group checkpointGroup) {
  1360→	// Checkpoint ID (truncated for display)
  1361→	cpID := group.checkpointID
  1362→	if len(cpID) > checkpointIDDisplayLength {
  1363→		cpID = cpID[:checkpointIDDisplayLength]
  1364→	}
  1365→
  1366→	// Build status indicators
  1367→	// Skip [temporary] indicator when cpID is already "temporary" to avoid redundancy
  1368→	var indicators []string
  1369→	if group.isTask {
  1370→		indicators = append(indicators, "[task]")
  1371→	}
  1372→	if group.isTemporary && cpID != "temporary" {
  1373→		indicators = append(indicators, "[temporary]")
  1374→	}
  1375→
  1376→	indicatorStr := ""
  1377→	if len(indicators) > 0 {
  1378→		indicatorStr = " " + strings.Join(indicators, " ")
  1379→	}
  1380→
  1381→	// Prompt (truncated)
  1382→	var promptStr string
  1383→	if group.prompt == "" {
  1384→		promptStr = "(no prompt)"
  1385→	} else {
  1386→		// Quote actual prompts
  1387→		promptStr = fmt.Sprintf("%q", strategy.TruncateDescription(group.prompt, maxPromptDisplayLength))
  1388→	}
  1389→
  1390→	// Checkpoint header: [checkpoint_id] [indicators] prompt
  1391→	fmt.Fprintf(sb, "[%s]%s %s\n", cpID, indicatorStr, promptStr)
  1392→
  1393→	// List commits under this checkpoint
  1394→	for _, commit := range group.commits {
  1395→		// Format: "  MM-DD HH:MM (git_sha) message"
  1396→		dateTimeStr := commit.date.Format("01-02 15:04")
  1397→		message := strategy.TruncateDescription(commit.message, maxMessageDisplayLength)
  1398→		fmt.Fprintf(sb, "  %s (%s) %s\n", dateTimeStr, commit.gitSHA, message)
  1399→	}
  1400→}
