  1402→// hasCodeChanges returns true if the commit has changes to non-metadata files.
  1403→// Used by getBranchCheckpoints to filter out metadata-only temporary checkpoints.
  1404→// Returns false only if the commit has a parent AND only modified .entire/ metadata files.
  1405→//
  1406→// First commits (no parent) are always considered to have code changes since they
  1407→// capture the working copy state at session start - real uncommitted work.
  1408→//
  1409→// This filters out periodic transcript saves that don't change code.
  1410→func hasCodeChanges(commit *object.Commit) bool {
  1411→	// First commit on shadow branch captures working copy state - always meaningful
  1412→	if commit.NumParents() == 0 {
  1413→		return true
  1414→	}
  1415→
  1416→	parent, err := commit.Parent(0)
  1417→	if err != nil {
  1418→		return true // Can't check, assume meaningful
  1419→	}
  1420→
  1421→	commitTree, err := commit.Tree()
  1422→	if err != nil {
  1423→		return true
  1424→	}
  1425→
  1426→	parentTree, err := parent.Tree()
  1427→	if err != nil {
  1428→		return true
  1429→	}
  1430→
  1431→	changes, err := parentTree.Diff(commitTree)
  1432→	if err != nil {
  1433→		return true
  1434→	}
  1435→
  1436→	// Check if any non-metadata file was changed
  1437→	for _, change := range changes {
  1438→		name := change.To.Name
  1439→		if name == "" {
  1440→			name = change.From.Name
  1441→		}
  1442→		// Skip .entire/ metadata files
  1443→		if !strings.HasPrefix(name, ".entire/") {
  1444→			return true
  1445→		}
  1446→	}
  1447→
  1448→	return false
  1449→}
