   795→// UpdateSummary updates the summary field in an existing checkpoint's metadata.
   796→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   797→func (s *GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
   798→	_ = ctx // Reserved for future use
   799→
   800→	// Ensure sessions branch exists
   801→	if err := s.ensureSessionsBranch(); err != nil {
   802→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
   803→	}
   804→
   805→	// Get current branch tip and flatten tree
   806→	ref, entries, err := s.getSessionsBranchEntries()
   807→	if err != nil {
   808→		return err
   809→	}
   810→
   811→	// Read existing metadata
   812→	basePath := checkpointID.Path() + "/"
   813→	metadataPath := basePath + paths.MetadataFileName
   814→	entry, exists := entries[metadataPath]
   815→	if !exists {
   816→		return ErrCheckpointNotFound
   817→	}
   818→
   819→	// Read and parse existing metadata
   820→	existingMetadata, err := s.readMetadataFromBlob(entry.Hash)
   821→	if err != nil {
   822→		return fmt.Errorf("failed to read existing metadata: %w", err)
   823→	}
   824→
   825→	// Update the summary
   826→	existingMetadata.Summary = summary
   827→
   828→	// Write updated metadata
   829→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
   830→	if err != nil {
   831→		return fmt.Errorf("failed to marshal metadata: %w", err)
   832→	}
   833→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   834→	if err != nil {
   835→		return fmt.Errorf("failed to create metadata blob: %w", err)
   836→	}
   837→	entries[metadataPath] = object.TreeEntry{
   838→		Name: metadataPath,
   839→		Mode: filemode.Regular,
   840→		Hash: metadataHash,
   841→	}
   842→
   843→	// Build and commit
   844→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
   845→	if err != nil {
   846→		return err
   847→	}
   848→
   849→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
   850→	commitMsg := fmt.Sprintf("Update summary: %s", checkpointID)
   851→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
   852→	if err != nil {
   853→		return err
   854→	}
   855→
   856→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   857→	newRef := plumbing.NewHashReference(refName, newCommitHash)
   858→	if err := s.repo.Storer.SetReference(newRef); err != nil {
   859→		return fmt.Errorf("failed to set branch reference: %w", err)
   860→	}
   861→
   862→	return nil
   863→}
