   865→// ensureSessionsBranch ensures the entire/sessions branch exists.
   866→func (s *GitStore) ensureSessionsBranch() error {
   867→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   868→	_, err := s.repo.Reference(refName, true)
   869→	if err == nil {
   870→		return nil // Branch exists
   871→	}
   872→
   873→	// Create orphan branch with empty tree
   874→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
   875→	if err != nil {
   876→		return err
   877→	}
   878→
   879→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
   880→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
   881→	if err != nil {
   882→		return err
   883→	}
   884→
   885→	newRef := plumbing.NewHashReference(refName, commitHash)
   886→	if err := s.repo.Storer.SetReference(newRef); err != nil {
   887→		return fmt.Errorf("failed to set branch reference: %w", err)
   888→	}
   889→	return nil
   890→}
