   992→// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
   993→func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
   994→	// Get repository config (includes local settings)
   995→	cfg, err := repo.Config()
   996→	if err == nil {
   997→		name = cfg.User.Name
   998→		email = cfg.User.Email
   999→	}
  1000→
  1001→	// Provide sensible defaults if git user is not configured
  1002→	if name == "" {
  1003→		name = "Unknown"
  1004→	}
  1005→	if email == "" {
  1006→		email = "unknown@local"
  1007→	}
  1008→
  1009→	return name, email
  1010→}
