   216→// extractUserPromptAt extracts the user prompt at the given index.
   217→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   218→func extractUserPromptAt(transcript []transcriptLine, idx int) string {
   219→	if idx >= len(transcript) || transcript[idx].Type != transcriptTypeUser {
   220→		return ""
   221→	}
   222→
   223→	var msg userMessage
   224→	if err := json.Unmarshal(transcript[idx].Message, &msg); err != nil {
   225→		return ""
   226→	}
   227→
   228→	// Handle string content
   229→	if str, ok := msg.Content.(string); ok {
   230→		return textutil.StripIDEContextTags(str)
   231→	}
   232→
   233→	// Handle array content (only if it contains text blocks)
   234→	if arr, ok := msg.Content.([]interface{}); ok {
   235→		var texts []string
   236→		for _, item := range arr {
   237→			if m, ok := item.(map[string]interface{}); ok {
   238→				if m["type"] == contentTypeText {
   239→					if text, ok := m["text"].(string); ok {
   240→						texts = append(texts, text)
   241→					}
   242→				}
   243→			}
   244→		}
   245→		if len(texts) > 0 {
   246→			return textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   247→		}
   248→	}
   249→
   250→	return ""
   251→}
