   314→// extractLastUserPrompt extracts the last user message from the transcript.
   315→// Only considers messages with string content (not tool results).
   316→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   317→func extractLastUserPrompt(transcript []transcriptLine) string {
   318→	prompts := extractUserPrompts(transcript)
   319→	if len(prompts) == 0 {
