   325→// extractLastAssistantMessage extracts the last text message from the assistant
   326→func extractLastAssistantMessage(transcript []transcriptLine) string {
   327→	for i := len(transcript) - 1; i >= 0; i-- {
   328→		if transcript[i].Type == transcriptTypeAssistant {
   329→			var msg assistantMessage
   330→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   331→				continue
   332→			}
   333→
   334→			for _, block := range msg.Content {
   335→				if block.Type == contentTypeText && block.Text != "" {
   336→					return block.Text
   337→				}
   338→			}
   339→		}
   340→	}
   341→	return ""
   342→}
