   344→// findLastUserUUID finds the UUID of the last user message (that has string content)
   345→func findLastUserUUID(transcript []transcriptLine) string {
   346→	for i := len(transcript) - 1; i >= 0; i-- {
   347→		if transcript[i].Type == transcriptTypeUser {
   348→			var msg userMessage
   349→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   350→				continue
   351→			}
   352→			// Only count messages with string content (not tool results)
   353→			if _, ok := msg.Content.(string); ok {
   354→				return transcript[i].UUID
   355→			}
   356→		}
   357→	}
   358→	return ""
