   361→// filterTranscriptAfterUUID returns transcript lines after the given UUID
   362→func filterTranscriptAfterUUID(transcript []transcriptLine, uuid string) []transcriptLine {
   363→	if uuid == "" {
   364→		return transcript
   365→	}
   366→
   367→	foundIndex := -1
   368→	for i, line := range transcript {
   369→		if line.UUID == uuid {
   370→			foundIndex = i
   371→			break
   372→		}
   373→	}
   374→
   375→	if foundIndex == -1 || foundIndex == len(transcript)-1 {
   376→		return transcript
   377→	}
   378→
   379→	return transcript[foundIndex+1:]
   380→}
