   382→// extractModifiedFiles extracts the list of files modified by tool calls
   383→func extractModifiedFiles(transcript []transcriptLine) []string {
   384→	fileSet := make(map[string]bool)
   385→	var files []string
   386→
   387→	for _, line := range transcript {
   388→		if line.Type == transcriptTypeAssistant {
   389→			var msg assistantMessage
   390→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   391→				continue
   392→			}
   393→
   394→			for _, block := range msg.Content {
   395→				if block.Type == contentTypeToolUse {
   396→					isModifyTool := false
   397→					for _, name := range claudecode.FileModificationTools {
   398→						if block.Name == name {
   399→							isModifyTool = true
   400→							break
   401→						}
   402→					}
   403→
   404→					if isModifyTool {
   405→						var input toolInput
   406→						if err := json.Unmarshal(block.Input, &input); err != nil {
   407→							continue
   408→						}
   409→
   410→						file := input.FilePath
   411→						if file == "" {
   412→							file = input.NotebookPath
   413→						}
   414→
   415→						if file != "" && !fileSet[file] {
   416→							fileSet[file] = true
   417→							files = append(files, file)
   418→						}
   419→					}
   420→				}
   421→			}
   422→		}
   423→	}
   424→
   425→	return files
   426→}
