   428→// extractKeyActions extracts key actions from the transcript for context file
   429→func extractKeyActions(transcript []transcriptLine, maxActions int) []string {
   430→	var keyActions []string
   431→
   432→	for _, line := range transcript {
   433→		if line.Type == transcriptTypeAssistant {
   434→			var msg assistantMessage
   435→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   436→				continue
   437→			}
   438→
   439→			for _, block := range msg.Content {
   440→				if block.Type == contentTypeToolUse {
   441→					var input toolInput
   442→					_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing for display purposes
   443→
   444→					detail := input.Description
   445→					if detail == "" {
   446→						detail = input.Command
   447→					}
   448→					if detail == "" {
   449→						detail = input.FilePath
   450→					}
   451→					if detail == "" {
   452→						detail = input.Pattern
   453→					}
   454→
   455→					action := "- **" + block.Name + "**: " + detail
   456→					keyActions = append(keyActions, action)
   457→					if len(keyActions) >= maxActions {
   458→						return keyActions
   459→					}
   460→				}
   461→			}
   462→		}
   463→	}
   464→
   465→	return keyActions
   466→}
