   486→// FindCheckpointUUID finds the UUID of the message containing the tool_result
   487→// for the given tool_use_id. This is used to find the checkpoint point for
   488→// transcript truncation when rewinding to a task.
   489→// Returns the UUID and true if found, empty string and false otherwise.
   490→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
   491→	for _, line := range transcript {
   492→		if line.Type != transcriptTypeUser {
   493→			continue
   494→		}
   495→
   496→		var msg userMessageWithToolResults
   497→		if err := json.Unmarshal(line.Message, &msg); err != nil {
   498→			continue
   499→		}
   500→
   501→		for _, block := range msg.Content {
   502→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
   503→				return line.UUID, true
   504→			}
   505→		}
   506→	}
   507→	return "", false
   508→}
