   510→// TruncateTranscriptAtUUID returns transcript lines up to and including the
   511→// line with the given UUID. If the UUID is not found or is empty, returns
   512→// the entire transcript.
   513→//
   514→//nolint:revive // Exported for testing purposes
   515→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
   516→	if uuid == "" {
   517→		return transcript
   518→	}
   519→
   520→	for i, line := range transcript {
   521→		if line.UUID == uuid {
   522→			return transcript[:i+1]
   523→		}
   524→	}
   525→
   526→	// UUID not found, return full transcript
   527→	return transcript
   528→}
