   530→// writeTranscript writes transcript lines to a file in JSONL format.
   531→func writeTranscript(path string, transcript []transcriptLine) error {
   532→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
   533→	if err != nil {
   534→		return fmt.Errorf("failed to create file: %w", err)
   535→	}
   536→	defer func() { _ = file.Close() }()
   537→
   538→	for _, line := range transcript {
   539→		data, err := json.Marshal(line)
   540→		if err != nil {
   541→			return fmt.Errorf("failed to marshal line: %w", err)
   542→		}
   543→		if _, err := file.Write(data); err != nil {
   544→			return fmt.Errorf("failed to write line: %w", err)
   545→		}
   546→		if _, err := file.WriteString("\n"); err != nil {
   547→			return fmt.Errorf("failed to write newline: %w", err)
   548→		}
   549→	}
   550→
   551→	return nil
   552→}
