   560→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
   561→// Returns empty position if file doesn't exist or is empty.
   562→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
   563→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
   564→	if path == "" {
   565→		return TranscriptPosition{}, nil
   566→	}
   567→
   568→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
   569→	if err != nil {
   570→		if os.IsNotExist(err) {
   571→			return TranscriptPosition{}, nil
   572→		}
   573→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
   574→	}
   575→	defer func() { _ = file.Close() }()
   576→
   577→	var pos TranscriptPosition
   578→	reader := bufio.NewReader(file)
   579→
   580→	for {
   581→		lineBytes, err := reader.ReadBytes('\n')
   582→		if err != nil && err != io.EOF {
   583→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
   584→		}
   585→
   586→		if len(lineBytes) == 0 {
   587→			if err == io.EOF {
   588→				break
   589→			}
   590→			continue
   591→		}
   592→
   593→		pos.LineCount++
   594→
   595→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
   596→		var line transcriptLine
   597→		if err := json.Unmarshal(lineBytes, &line); err == nil {
   598→			if line.UUID != "" {
   599→				pos.LastUUID = line.UUID
   600→			}
   601→		}
   602→
   603→		if err == io.EOF {
   604→			break
   605→		}
   606→	}
   607→
   608→	return pos, nil
   609→}
