   444→// readMetadataFromBlob reads CommittedMetadata from a blob hash.
   445→func (s *GitStore) readMetadataFromBlob(hash plumbing.Hash) (*CommittedMetadata, error) {
   446→	blob, err := s.repo.BlobObject(hash)
   447→	if err != nil {
   448→		return nil, fmt.Errorf("failed to get blob: %w", err)
   449→	}
   450→
   451→	reader, err := blob.Reader()
   452→	if err != nil {
   453→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
   454→	}
   455→	defer reader.Close()
   456→
   457→	var metadata CommittedMetadata
   458→	if err := json.NewDecoder(reader).Decode(&metadata); err != nil {
   459→		return nil, fmt.Errorf("failed to decode metadata: %w", err)
   460→	}
   461→
   462→	return &metadata, nil
   463→}
