   564→// buildCommitMessage constructs the commit message with proper trailers.
   565→// The commit subject is always "Checkpoint: <id>" for consistency.
   566→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
   567→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
   568→	var commitMsg strings.Builder
   569→
   570→	// Subject line is always the checkpoint ID for consistent formatting
   571→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
   572→
   573→	// Include custom description in body if provided (e.g., task checkpoint details)
   574→	if opts.CommitSubject != "" {
   575→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
   576→	}
   577→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
   578→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
   579→	if opts.Agent != "" {
   580→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
   581→	}
   582→	if opts.EphemeralBranch != "" {
   583→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
   584→	}
   585→	if taskMetadataPath != "" {
   586→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath))
   587→	}
   588→
   589→	return commitMsg.String()
   590→}
