   666→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   667→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   668→//
   669→
   670→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   671→	_ = ctx // Reserved for future use
   672→
   673→	tree, err := s.getSessionsBranchTree()
   674→	if err != nil {
   675→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   676→	}
   677→
   678→	var checkpoints []CommittedInfo
   679→
   680→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   681→	for _, bucketEntry := range tree.Entries {
   682→		if bucketEntry.Mode != filemode.Dir {
   683→			continue
   684→		}
   685→		// Bucket should be 2 hex chars
   686→		if len(bucketEntry.Name) != 2 {
   687→			continue
   688→		}
   689→
   690→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   691→		if treeErr != nil {
   692→			continue
   693→		}
   694→
   695→		// Each entry in the bucket is the remaining part of the checkpoint ID
   696→		for _, checkpointEntry := range bucketTree.Entries {
   697→			if checkpointEntry.Mode != filemode.Dir {
   698→				continue
   699→			}
   700→
   701→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   702→			if cpTreeErr != nil {
   703→				continue
   704→			}
   705→
   706→			// Reconstruct checkpoint ID: <bucket><remaining>
   707→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   708→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
   709→			if cpIDErr != nil {
   710→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
   711→				continue
   712→			}
   713→
   714→			info := CommittedInfo{
   715→				CheckpointID: checkpointID,
   716→			}
   717→
   718→			// Get details from metadata file
   719→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   720→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   721→					var metadata CommittedMetadata
   722→					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
   723→						info.SessionID = metadata.SessionID
   724→						info.CreatedAt = metadata.CreatedAt
   725→						info.CheckpointsCount = metadata.CheckpointsCount
   726→						info.FilesTouched = metadata.FilesTouched
   727→						info.Agent = metadata.Agent
   728→						info.IsTask = metadata.IsTask
   729→						info.ToolUseID = metadata.ToolUseID
   730→						info.SessionCount = metadata.SessionCount
   731→						info.SessionIDs = metadata.SessionIDs
   732→					}
   733→				}
   734→			}
   735→
   736→			checkpoints = append(checkpoints, info)
   737→		}
   738→	}
   739→
   740→	// Sort by time (most recent first)
   741→	sort.Slice(checkpoints, func(i, j int) bool {
   742→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   743→	})
   744→
   745→	return checkpoints, nil
   746→}
