   913→// CreateBlobFromContent creates a blob object from in-memory content.
   914→// Exported for use by strategy package (session_test.go)
   915→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
   916→	obj := repo.Storer.NewEncodedObject()
   917→	obj.SetType(plumbing.BlobObject)
   918→	obj.SetSize(int64(len(content)))
   919→
   920→	writer, err := obj.Writer()
   921→	if err != nil {
   922→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
   923→	}
   924→
   925→	_, err = writer.Write(content)
   926→	if err != nil {
   927→		_ = writer.Close()
   928→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
   929→	}
   930→	if err := writer.Close(); err != nil {
   931→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
   932→	}
   933→
   934→	hash, err := repo.Storer.SetEncodedObject(obj)
   935→	if err != nil {
   936→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
   937→	}
   938→	return hash, nil
   939→}
