   941→// copyMetadataDir copies all files from a directory to the checkpoint path.
   942→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
   943→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
   944→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
   945→		if err != nil {
   946→			return err
   947→		}
   948→		if info.IsDir() {
   949→			return nil
   950→		}
   951→
   952→		// Skip symlinks to prevent reading files outside the metadata directory.
   953→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
   954→		// then be captured in the checkpoint and stored in git history.
   955→		if info.Mode()&os.ModeSymlink != 0 {
   956→			return nil
   957→		}
   958→
   959→		// Get relative path within metadata dir
   960→		relPath, err := filepath.Rel(metadataDir, path)
   961→		if err != nil {
   962→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
   963→		}
   964→
   965→		// Prevent path traversal via symlinks pointing outside the metadata dir
   966→		if strings.HasPrefix(relPath, "..") {
   967→			return fmt.Errorf("path traversal detected: %s", relPath)
   968→		}
   969→
   970→		// Create blob from file
   971→		blobHash, mode, err := createBlobFromFile(s.repo, path)
   972→		if err != nil {
   973→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
   974→		}
   975→
   976→		// Store at checkpoint path
   977→		fullPath := basePath + relPath
   978→		entries[fullPath] = object.TreeEntry{
   979→			Name: fullPath,
   980→			Mode: mode,
   981→			Hash: blobHash,
   982→		}
   983→
   984→		return nil
   985→	})
   986→	if err != nil {
   987→		return fmt.Errorf("failed to walk metadata directory: %w", err)
   988→	}
   989→	return nil
   990→}
