  1012→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1013→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1014→// The agentType is used for reassembling chunks in the correct format.
  1015→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1016→	// Collect all transcript-related files
  1017→	var chunkFiles []string
  1018→	var hasBaseFile bool
  1019→
  1020→	for _, entry := range tree.Entries {
  1021→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1022→			hasBaseFile = true
  1023→		}
  1024→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1025→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1026→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1027→			if idx > 0 {
  1028→				chunkFiles = append(chunkFiles, entry.Name)
  1029→			}
  1030→		}
  1031→	}
  1032→
  1033→	// If we have chunk files, read and reassemble them
  1034→	if len(chunkFiles) > 0 {
  1035→		// Sort chunk files by index
  1036→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1037→
  1038→		// Check if base file should be included as chunk 0.
  1039→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1040→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1041→		if hasBaseFile {
  1042→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1043→		}
  1044→
  1045→		var chunks [][]byte
  1046→		for _, chunkFile := range chunkFiles {
  1047→			file, err := tree.File(chunkFile)
  1048→			if err != nil {
  1049→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1050→					slog.String("chunk_file", chunkFile),
  1051→					slog.String("error", err.Error()),
  1052→				)
  1053→				continue
  1054→			}
  1055→			content, err := file.Contents()
  1056→			if err != nil {
  1057→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1058→					slog.String("chunk_file", chunkFile),
  1059→					slog.String("error", err.Error()),
  1060→				)
  1061→				continue
  1062→			}
  1063→			chunks = append(chunks, []byte(content))
  1064→		}
  1065→
  1066→		if len(chunks) > 0 {
  1067→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1068→			if err != nil {
  1069→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1070→			}
  1071→			return result, nil
  1072→		}
  1073→	}
  1074→
  1075→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1076→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1077→		if content, err := file.Contents(); err == nil {
  1078→			return []byte(content), nil
  1079→		}
  1080→	}
  1081→
  1082→	// Try legacy filename
  1083→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1084→		if content, err := file.Contents(); err == nil {
  1085→			return []byte(content), nil
  1086→		}
  1087→	}
  1088→
  1089→	return nil, nil
  1090→}
