    71→		Use:   "explain",
    72→		Short: "Explain a session, commit, or checkpoint",
    73→		Long: `Explain provides human-readable context about sessions, commits, and checkpoints.
    74→
    75→Use this command to understand what happened during agent-driven development,
    76→either for self-review or to understand a teammate's work.
    77→
    78→By default, shows checkpoints on the current branch. Use flags to explain a specific
    79→session, commit, or checkpoint.
    80→
    81→Output verbosity levels (for --checkpoint):
    82→  Default:   Detailed view (ID, session, timestamp, tokens, intent, prompts, files)
    83→  --short:   Summary only (ID, session, timestamp, tokens, intent)
    84→  --full:    + complete transcript
    85→
    86→Summary generation (for --checkpoint):
    87→  --generate    Generate an AI summary for the checkpoint
    88→  --force       Regenerate even if a summary already exists (requires --generate)
    89→
    90→Only one of --session, --commit, or --checkpoint can be specified at a time.`,
    91→		RunE: func(cmd *cobra.Command, _ []string) error {
    92→			// Check if Entire is disabled
    93→			if checkDisabledGuard(cmd.OutOrStdout()) {
    94→				return nil
    95→			}
    96→
    97→			// Validate flag dependencies
    98→			if generateFlag && checkpointFlag == "" {
    99→				return errors.New("--generate requires --checkpoint/-c flag")
   100→			}
   101→			if forceFlag && !generateFlag {
   102→				return errors.New("--force requires --generate flag")
   103→			}
   104→
   105→			// Convert short flag to verbose (verbose = !short)
   106→			verbose := !shortFlag
   107→			return runExplain(cmd.OutOrStdout(), cmd.ErrOrStderr(), sessionFlag, commitFlag, checkpointFlag, noPagerFlag, verbose, fullFlag, generateFlag, forceFlag)
   108→		},
   109→	}
   110→
   111→	cmd.Flags().StringVar(&sessionFlag, "session", "", "Explain a specific session (ID or prefix)")
   112→	cmd.Flags().StringVar(&commitFlag, "commit", "", "Explain a specific commit (SHA or ref)")
   113→	cmd.Flags().StringVarP(&checkpointFlag, "checkpoint", "c", "", "Explain a specific checkpoint (ID or prefix)")
   114→	cmd.Flags().BoolVar(&noPagerFlag, "no-pager", false, "Disable pager output")
   115→	cmd.Flags().BoolVarP(&shortFlag, "short", "s", false, "Show summary only (omit prompts and files)")
   116→	cmd.Flags().BoolVar(&fullFlag, "full", false, "Show complete transcript")
   117→	cmd.Flags().BoolVar(&generateFlag, "generate", false, "Generate an AI summary for the checkpoint")
   118→	cmd.Flags().BoolVar(&forceFlag, "force", false, "Regenerate summary even if one already exists (requires --generate)")
   119→
   120→	return cmd
   121→}
