   123→// runExplain routes to the appropriate explain function based on flags.
   124→func runExplain(w, errW io.Writer, sessionID, commitRef, checkpointID string, noPager, verbose, full, generate, force bool) error {
   125→	// Count mutually exclusive flags
   126→	flagCount := 0
   127→	if sessionID != "" {
   128→		flagCount++
   129→	}
   130→	if commitRef != "" {
   131→		flagCount++
   132→	}
   133→	if checkpointID != "" {
   134→		flagCount++
   135→	}
   136→	if flagCount > 1 {
   137→		return errors.New("cannot specify multiple of --session, --commit, --checkpoint")
   138→	}
   139→
   140→	// Route to appropriate handler
   141→	if sessionID != "" {
   142→		return runExplainSession(w, sessionID, noPager)
   143→	}
   144→	if commitRef != "" {
   145→		return runExplainCommit(w, commitRef)
   146→	}
   147→	if checkpointID != "" {
   148→		return runExplainCheckpoint(w, errW, checkpointID, noPager, verbose, full, generate, force)
   149→	}
   150→
   151→	// Default: explain current session
   152→	return runExplainDefault(w, noPager)
   153→}
