   155→// runExplainCheckpoint explains a specific checkpoint.
   156→// Supports both committed checkpoints (by checkpoint ID) and temporary checkpoints (by git SHA).
   157→// First tries to match committed checkpoints, then falls back to temporary checkpoints.
   158→// When generate is true, generates an AI summary for the checkpoint.
   159→// When force is true, regenerates even if a summary already exists.
   160→func runExplainCheckpoint(w, errW io.Writer, checkpointIDPrefix string, noPager, verbose, full, generate, force bool) error {
   161→	repo, err := openRepository()
   162→	if err != nil {
   163→		return fmt.Errorf("not a git repository: %w", err)
   164→	}
   165→
   166→	store := checkpoint.NewGitStore(repo)
   167→
   168→	// First, try to find in committed checkpoints by checkpoint ID prefix
   169→	committed, err := store.ListCommitted(context.Background())
   170→	if err != nil {
   171→		return fmt.Errorf("failed to list checkpoints: %w", err)
   172→	}
   173→
   174→	// Collect all matching checkpoint IDs to detect ambiguity
   175→	var matches []id.CheckpointID
   176→	for _, info := range committed {
   177→		if strings.HasPrefix(info.CheckpointID.String(), checkpointIDPrefix) {
   178→			matches = append(matches, info.CheckpointID)
   179→		}
   180→	}
   181→
   182→	var fullCheckpointID id.CheckpointID
   183→	switch len(matches) {
   184→	case 0:
   185→		// Not found in committed, try temporary checkpoints by git SHA
   186→		if generate {
   187→			return fmt.Errorf("cannot generate summary for temporary checkpoint %s (only committed checkpoints supported)", checkpointIDPrefix)
   188→		}
   189→		output, found := explainTemporaryCheckpoint(repo, store, checkpointIDPrefix, verbose, full)
   190→		if found {
   191→			outputExplainContent(w, output, noPager)
   192→			return nil
   193→		}
   194→		return fmt.Errorf("checkpoint not found: %s", checkpointIDPrefix)
   195→	case 1:
   196→		fullCheckpointID = matches[0]
   197→	default:
   198→		// Ambiguous prefix - show up to 5 examples
   199→		examples := make([]string, 0, 5)
   200→		for i := 0; i < len(matches) && i < 5; i++ {
   201→			examples = append(examples, matches[i].String())
   202→		}
   203→		return fmt.Errorf("ambiguous checkpoint prefix %q matches %d checkpoints: %s", checkpointIDPrefix, len(matches), strings.Join(examples, ", "))
   204→	}
   205→
   206→	// Load checkpoint data
   207→	result, err := store.ReadCommitted(context.Background(), fullCheckpointID)
   208→	if err != nil {
   209→		return fmt.Errorf("failed to read checkpoint: %w", err)
   210→	}
   211→	if result == nil {
   212→		return fmt.Errorf("checkpoint not found: %s", fullCheckpointID)
   213→	}
   214→
   215→	// Handle summary generation
   216→	if generate {
   217→		if err := generateCheckpointSummary(w, errW, store, fullCheckpointID, result, force); err != nil {
   218→			return err
   219→		}
   220→		// Reload the result to get the updated summary
   221→		result, err = store.ReadCommitted(context.Background(), fullCheckpointID)
   222→		if err != nil {
   223→			return fmt.Errorf("failed to reload checkpoint: %w", err)
   224→		}
   225→	}
   226→
   227→	// Look up the commit message for this checkpoint
   228→	commitMessage := findCommitMessageForCheckpoint(repo, fullCheckpointID)
   229→
   230→	// Format and output
   231→	output := formatCheckpointOutput(result, fullCheckpointID, commitMessage, verbose, full)
   232→	outputExplainContent(w, output, noPager)
   233→	return nil
   234→}
