   381→// findCommitMessageForCheckpoint searches git history for a commit with the
   382→// Entire-Checkpoint trailer matching the given checkpoint ID, and returns
   383→// the first line of the commit message. Returns empty string if not found.
   384→func findCommitMessageForCheckpoint(repo *git.Repository, checkpointID id.CheckpointID) string {
   385→	// Get HEAD reference
   386→	head, err := repo.Head()
   387→	if err != nil {
   388→		return ""
   389→	}
   390→
   391→	// Iterate through commit history (limit to recent commits for performance)
   392→	commitIter, err := repo.Log(&git.LogOptions{
   393→		From: head.Hash(),
   394→	})
   395→	if err != nil {
   396→		return ""
   397→	}
   398→	defer commitIter.Close()
   399→
   400→	count := 0
   401→
   402→	for {
   403→		commit, iterErr := commitIter.Next()
   404→		if iterErr != nil {
   405→			break
   406→		}
   407→		count++
   408→		if count > commitScanLimit {
   409→			break
   410→		}
   411→
   412→		// Check if this commit has our checkpoint ID
   413→		foundID, hasTrailer := trailers.ParseCheckpoint(commit.Message)
   414→		if hasTrailer && foundID == checkpointID {
   415→			// Return first line of commit message (without trailing newline)
   416→			firstLine := strings.Split(commit.Message, "\n")[0]
   417→			return strings.TrimSpace(firstLine)
   418→		}
   419→	}
   420→
   421→	return ""
   422→}
