   424→// formatCheckpointOutput formats checkpoint data based on verbosity level.
   425→// When verbose is false: summary only (ID, session, timestamp, tokens, intent).
   426→// When verbose is true: adds prompts, files, and commit message details.
   427→// When full is true: includes the complete transcript in addition to verbose details.
   428→func formatCheckpointOutput(result *checkpoint.ReadCommittedResult, checkpointID id.CheckpointID, commitMessage string, verbose, full bool) string {
   429→	var sb strings.Builder
   430→	meta := result.Metadata
   431→
   432→	// Header - always shown
   433→	shortID := checkpointID
   434→	if len(shortID) > checkpointIDDisplayLength {
   435→		shortID = shortID[:checkpointIDDisplayLength]
   436→	}
   437→	fmt.Fprintf(&sb, "Checkpoint: %s\n", shortID)
   438→	fmt.Fprintf(&sb, "Session: %s\n", meta.SessionID)
   439→	fmt.Fprintf(&sb, "Created: %s\n", meta.CreatedAt.Format("2006-01-02 15:04:05"))
   440→
   441→	// Token usage
   442→	if meta.TokenUsage != nil {
   443→		totalTokens := meta.TokenUsage.InputTokens + meta.TokenUsage.CacheCreationTokens +
   444→			meta.TokenUsage.CacheReadTokens + meta.TokenUsage.OutputTokens
   445→		fmt.Fprintf(&sb, "Tokens: %d\n", totalTokens)
   446→	}
   447→
   448→	sb.WriteString("\n")
   449→
   450→	// Intent and Outcome from AI summary, or fallback to prompt text
   451→	if meta.Summary != nil {
   452→		fmt.Fprintf(&sb, "Intent: %s\n", meta.Summary.Intent)
   453→		fmt.Fprintf(&sb, "Outcome: %s\n", meta.Summary.Outcome)
   454→	} else {
   455→		// Fallback: use first line of prompts for intent
   456→		intent := "(not generated)"
   457→		if result.Prompts != "" {
   458→			lines := strings.Split(result.Prompts, "\n")
   459→			if len(lines) > 0 && lines[0] != "" {
   460→				intent = strategy.TruncateDescription(lines[0], maxIntentDisplayLength)
   461→			}
   462→		}
   463→		fmt.Fprintf(&sb, "Intent: %s\n", intent)
   464→		sb.WriteString("Outcome: (not generated)\n")
   465→	}
   466→
   467→	// Verbose: add commit message, learnings, friction, files, and prompts
   468→	if verbose || full {
   469→		// AI Summary details (learnings, friction, open items)
   470→		if meta.Summary != nil {
   471→			formatSummaryDetails(&sb, meta.Summary)
   472→		}
   473→
   474→		// Commit message section (only if available)
   475→		if commitMessage != "" {
   476→			sb.WriteString("\n")
   477→			fmt.Fprintf(&sb, "Commit: %s\n", commitMessage)
   478→		}
   479→
   480→		sb.WriteString("\n")
   481→
   482→		// Files section
   483→		if len(meta.FilesTouched) > 0 {
   484→			fmt.Fprintf(&sb, "Files: (%d)\n", len(meta.FilesTouched))
   485→			for _, file := range meta.FilesTouched {
   486→				fmt.Fprintf(&sb, "  - %s\n", file)
   487→			}
   488→		} else {
   489→			sb.WriteString("Files: (none)\n")
   490→		}
   491→
   492→		sb.WriteString("\n")
   493→
   494→		// Prompts section
   495→		sb.WriteString("Prompts:\n")
   496→		if result.Prompts != "" {
   497→			sb.WriteString(result.Prompts)
   498→			sb.WriteString("\n")
   499→		} else {
   500→			sb.WriteString("  (none)\n")
   501→		}
   502→	}
   503→
   504→	// Full: add transcript
   505→	if full {
   506→		sb.WriteString("\n")
   507→		sb.WriteString("Transcript:\n")
   508→		if len(result.Transcript) > 0 {
   509→			sb.Write(result.Transcript)
   510→			sb.WriteString("\n")
   511→		} else {
   512→			sb.WriteString("  (none)\n")
   513→		}
   514→	}
   515→
   516→	return sb.String()
   517→}
