   582→// branchCheckpointsLimit is the max checkpoints to show in branch view
   583→const branchCheckpointsLimit = 100
   584→
   585→// commitScanLimit is how far back to scan git history for checkpoints
   586→const commitScanLimit = 500
   587→
   588→// consecutiveMainLimit stops scanning after this many consecutive commits on main
   589→// (indicates we've likely exhausted feature branch commits)
   590→const consecutiveMainLimit = 100
   591→
   592→// errStopIteration is used to stop commit iteration early
   593→var errStopIteration = errors.New("stop iteration")
   594→
   595→// getBranchCheckpoints returns checkpoints relevant to the current branch.
   596→// This is strategy-agnostic - it queries checkpoints directly from the checkpoint store.
   597→//
   598→// Behavior:
   599→//   - On feature branches: only show checkpoints unique to this branch (not in main)
   600→//   - On default branch (main/master): show all checkpoints in history (up to limit)
   601→//   - Includes both committed checkpoints (entire/sessions) and temporary checkpoints (shadow branches)
   602→func getBranchCheckpoints(repo *git.Repository, limit int) ([]strategy.RewindPoint, error) {
   603→	store := checkpoint.NewGitStore(repo)
   604→
   605→	// Get all committed checkpoints for lookup
   606→	committedInfos, err := store.ListCommitted(context.Background())
   607→	if err != nil {
   608→		committedInfos = nil // Continue without committed checkpoints
   609→	}
   610→
   611→	// Build map of checkpoint ID -> committed info
   612→	committedByID := make(map[id.CheckpointID]checkpoint.CommittedInfo)
   613→	for _, info := range committedInfos {
   614→		if !info.CheckpointID.IsEmpty() {
   615→			committedByID[info.CheckpointID] = info
   616→		}
   617→	}
   618→
   619→	head, err := repo.Head()
   620→	if err != nil {
   621→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
   622→	}
   623→
   624→	// Check if we're on the default branch (use repo-aware version)
   625→	isOnDefault, _ := strategy.IsOnDefaultBranch(repo)
   626→	var mainBranchHash plumbing.Hash
   627→	if !isOnDefault {
   628→		mainBranchHash = strategy.GetMainBranchHash(repo)
   629→	}
   630→
   631→	// Walk git history and collect checkpoints
   632→	iter, err := repo.Log(&git.LogOptions{
   633→		From:  head.Hash(),
   634→		Order: git.LogOrderCommitterTime,
   635→	})
   636→	if err != nil {
   637→		return nil, fmt.Errorf("failed to get commit log: %w", err)
   638→	}
   639→	defer iter.Close()
   640→
   641→	// Fetch metadata branch tree once (used for reading session prompts)
   642→	metadataTree, _ := strategy.GetMetadataBranchTree(repo) //nolint:errcheck // Best-effort, continue without prompts
   643→
   644→	var points []strategy.RewindPoint
   645→	count := 0
   646→	consecutiveMainCount := 0
   647→
   648→	err = iter.ForEach(func(c *object.Commit) error {
   649→		if count >= commitScanLimit {
   650→			return errStopIteration
   651→		}
   652→		count++
   653→
   654→		// On feature branches, skip commits that are reachable from main
   655→		// (but continue scanning - there may be more feature branch commits)
   656→		if mainBranchHash != plumbing.ZeroHash {
   657→			if isAncestorOf(repo, c.Hash, mainBranchHash) {
   658→				consecutiveMainCount++
   659→				if consecutiveMainCount >= consecutiveMainLimit {
   660→					return errStopIteration // Likely exhausted feature branch commits
   661→				}
   662→				return nil // Skip this commit, continue scanning
   663→			}
   664→			consecutiveMainCount = 0 // Reset on feature branch commit
   665→		}
   666→
   667→		// Extract checkpoint ID from Entire-Checkpoint trailer
   668→		cpID, found := trailers.ParseCheckpoint(c.Message)
   669→		if !found {
   670→			return nil // No checkpoint trailer, continue
   671→		}
   672→
   673→		// Look up checkpoint info
   674→		cpInfo, found := committedByID[cpID]
   675→		if !found {
   676→			return nil // Checkpoint not in store, continue
   677→		}
   678→
   679→		// Create rewind point from committed info
   680→		message := strings.Split(c.Message, "\n")[0]
   681→		point := strategy.RewindPoint{
   682→			ID:           c.Hash.String(),
   683→			Message:      message,
   684→			Date:         c.Author.When,
   685→			IsLogsOnly:   true, // Committed checkpoints are logs-only
   686→			CheckpointID: cpID,
   687→			SessionID:    cpInfo.SessionID,
   688→		}
   689→
   690→		// Read session prompt from metadata branch (best-effort)
   691→		if metadataTree != nil {
   692→			point.SessionPrompt = strategy.ReadSessionPromptFromTree(metadataTree, cpID.Path())
   693→		}
   694→
   695→		points = append(points, point)
   696→		return nil
   697→	})
   698→
   699→	if err != nil && !errors.Is(err, errStopIteration) {
   700→		return nil, fmt.Errorf("error iterating commits: %w", err)
   701→	}
   702→
   703→	// Also get temporary checkpoints from shadow branch for current HEAD
   704→	headShort := head.Hash().String()[:7]
   705→	tempCheckpoints, _ := store.ListTemporaryCheckpoints(context.Background(), headShort, "", limit) //nolint:errcheck // Best-effort, continue without temp checkpoints
   706→	for _, tc := range tempCheckpoints {
   707→		shadowCommit, commitErr := repo.CommitObject(tc.CommitHash)
   708→		if commitErr != nil {
   709→			continue
   710→		}
   711→
   712→		// Filter out checkpoints with no code changes (only .entire/ metadata changed)
   713→		// This also filters out the first checkpoint which is just a baseline copy
   714→		if !hasCodeChanges(shadowCommit) {
   715→			continue
   716→		}
   717→
   718→		// Read session prompt from the shadow branch commit's tree (not from entire/sessions)
   719→		// Temporary checkpoints store their metadata in the shadow branch, not in entire/sessions
   720→		var sessionPrompt string
   721→		shadowTree, treeErr := shadowCommit.Tree()
   722→		if treeErr == nil {
   723→			sessionPrompt = strategy.ReadSessionPromptFromTree(shadowTree, tc.MetadataDir)
   724→		}
   725→
   726→		points = append(points, strategy.RewindPoint{
   727→			ID:               tc.CommitHash.String(),
   728→			Message:          tc.Message,
   729→			MetadataDir:      tc.MetadataDir,
   730→			Date:             tc.Timestamp,
   731→			IsTaskCheckpoint: tc.IsTaskCheckpoint,
   732→			ToolUseID:        tc.ToolUseID,
   733→			SessionID:        tc.SessionID,
   734→			SessionPrompt:    sessionPrompt,
   735→			IsLogsOnly:       false, // Temporary checkpoints can be fully rewound
   736→		})
   737→	}
   738→
   739→	// Sort by date, most recent first
   740→	sort.Slice(points, func(i, j int) bool {
   741→		return points[i].Date.After(points[j].Date)
   742→	})
   743→
   744→	// Apply limit
   745→	if len(points) > limit {
   746→		points = points[:limit]
   747→	}
   748→
   749→	return points, nil
   750→}
