   979→// runExplainCommit explains a specific commit.
   980→func runExplainCommit(w io.Writer, commitRef string) error {
   981→	repo, err := openRepository()
   982→	if err != nil {
   983→		return fmt.Errorf("not a git repository: %w", err)
   984→	}
   985→
   986→	// Resolve the commit reference
   987→	hash, err := repo.ResolveRevision(plumbing.Revision(commitRef))
   988→	if err != nil {
   989→		return fmt.Errorf("commit not found: %s", commitRef)
   990→	}
   991→
   992→	commit, err := repo.CommitObject(*hash)
   993→	if err != nil {
   994→		return fmt.Errorf("failed to get commit: %w", err)
   995→	}
   996→
   997→	// Get files changed in this commit (diff from parent to current)
   998→	var files []string
   999→	commitTree, err := commit.Tree()
  1000→	if err == nil && commit.NumParents() > 0 {
  1001→		parent, parentErr := commit.Parent(0)
  1002→		if parentErr == nil {
  1003→			parentTree, treeErr := parent.Tree()
  1004→			if treeErr == nil {
  1005→				// Diff from parent to current commit to show what changed
  1006→				changes, diffErr := parentTree.Diff(commitTree)
  1007→				if diffErr == nil {
  1008→					for _, change := range changes {
  1009→						name := change.To.Name
  1010→						if name == "" {
  1011→							name = change.From.Name
  1012→						}
  1013→						files = append(files, name)
  1014→					}
  1015→				}
  1016→			}
  1017→		}
  1018→	}
  1019→
  1020→	// Check for Entire metadata - try multiple trailer types
  1021→	metadataDir, hasMetadata := trailers.ParseMetadata(commit.Message)
  1022→	sessionID, hasSession := trailers.ParseSession(commit.Message)
  1023→	checkpointID, hasCheckpoint := trailers.ParseCheckpoint(commit.Message)
  1024→
  1025→	// If no session trailer, try to extract from metadata path.
  1026→	// Note: extractSessionIDFromMetadata is defined in rewind.go as it's used
  1027→	// by both the rewind and explain commands for parsing metadata paths.
  1028→	if !hasSession && hasMetadata {
  1029→		sessionID = extractSessionIDFromMetadata(metadataDir)
  1030→		hasSession = sessionID != ""
  1031→	}
  1032→
  1033→	// Build commit info
  1034→	fullSHA := hash.String()
  1035→	shortSHA := fullSHA
  1036→	if len(fullSHA) >= 7 {
  1037→		shortSHA = fullSHA[:7]
  1038→	}
  1039→
  1040→	info := &commitInfo{
  1041→		SHA:       fullSHA,
  1042→		ShortSHA:  shortSHA,
  1043→		Message:   strings.Split(commit.Message, "\n")[0], // First line only
  1044→		Author:    commit.Author.Name,
  1045→		Email:     commit.Author.Email,
  1046→		Date:      commit.Author.When,
  1047→		Files:     files,
  1048→		HasEntire: hasMetadata || hasSession || hasCheckpoint,
  1049→		SessionID: sessionID,
  1050→	}
  1051→
  1052→	// If we have a checkpoint ID but no session, try to look up session from metadata
  1053→	if hasCheckpoint && sessionID == "" {
  1054→		if result, err := checkpoint.NewGitStore(repo).ReadCommitted(context.Background(), checkpointID); err == nil && result != nil {
  1055→			info.SessionID = result.Metadata.SessionID
  1056→		}
  1057→	}
  1058→
  1059→	// Format and output
  1060→	output := formatCommitInfo(info)
  1061→	fmt.Fprint(w, output)
  1062→
  1063→	return nil
  1064→}
