  1148→// formatCommitInfo formats commit information for display.
  1149→func formatCommitInfo(info *commitInfo) string {
  1150→	var sb strings.Builder
  1151→
  1152→	fmt.Fprintf(&sb, "Commit: %s (%s)\n", info.SHA, info.ShortSHA)
  1153→	fmt.Fprintf(&sb, "Date: %s\n", info.Date.Format("2006-01-02 15:04:05"))
  1154→
  1155→	if info.HasEntire && info.SessionID != "" {
  1156→		fmt.Fprintf(&sb, "Session: %s\n", info.SessionID)
  1157→	}
  1158→
  1159→	sb.WriteString("\n")
  1160→
  1161→	// Message
  1162→	sb.WriteString("Message:\n")
  1163→	fmt.Fprintf(&sb, "  %s\n", info.Message)
  1164→	sb.WriteString("\n")
  1165→
  1166→	// Files modified
  1167→	if len(info.Files) > 0 {
  1168→		fmt.Fprintf(&sb, "Files Modified (%d):\n", len(info.Files))
  1169→		for _, file := range info.Files {
  1170→			fmt.Fprintf(&sb, "  - %s\n", file)
  1171→		}
  1172→		sb.WriteString("\n")
  1173→	}
  1174→
  1175→	// Note for non-Entire commits
  1176→	if !info.HasEntire {
  1177→		sb.WriteString("Note: No Entire session data available for this commit.\n")
  1178→	}
  1179→
  1180→	return sb.String()
  1181→}
