  1183→// outputWithPager outputs content through a pager if stdout is a terminal and content is long.
  1184→func outputWithPager(w io.Writer, content string) {
  1185→	// Check if we're writing to stdout and it's a terminal
  1186→	if f, ok := w.(*os.File); ok && f == os.Stdout && term.IsTerminal(int(f.Fd())) {
  1187→		// Get terminal height
  1188→		_, height, err := term.GetSize(int(f.Fd()))
  1189→		if err != nil {
  1190→			height = 24 // Default fallback
  1191→		}
  1192→
  1193→		// Count lines in content
  1194→		lineCount := strings.Count(content, "\n")
  1195→
  1196→		// Use pager if content exceeds terminal height
  1197→		if lineCount > height-2 {
  1198→			pager := os.Getenv("PAGER")
  1199→			if pager == "" {
  1200→				pager = "less"
  1201→			}
  1202→
  1203→			cmd := exec.CommandContext(context.Background(), pager) //nolint:gosec // pager from env is expected
  1204→			cmd.Stdin = strings.NewReader(content)
