   148→// PromptResponsePair represents a user prompt and the assistant's responses.
   149→// Used for extracting all interactions from a transcript.
   150→type PromptResponsePair struct {
   151→	Prompt    string
   152→	Responses []string // Multiple responses can occur between tool calls
   153→	Files     []string
   154→}
   155→
   156→// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
   157→// Returns pairs in chronological order (oldest first).
   158→// Each pair contains the user's prompt, assistant's text response, and files modified.
   159→func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
   160→	var pairs []PromptResponsePair
   161→
   162→	// Find all user prompts (messages with string content, not tool results)
   163→	var userIndices []int
   164→	for i, line := range transcript {
   165→		if line.Type == transcriptTypeUser {
   166→			var msg userMessage
   167→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   168→				continue
   169→			}
   170→			// Only count messages with string content (real user prompts)
   171→			if _, ok := msg.Content.(string); ok {
   172→				userIndices = append(userIndices, i)
   173→			} else if arr, ok := msg.Content.([]interface{}); ok {
   174→				// Check if array has text blocks (also a real user prompt)
   175→				for _, item := range arr {
   176→					if m, ok := item.(map[string]interface{}); ok {
   177→						if m["type"] == contentTypeText {
   178→							userIndices = append(userIndices, i)
   179→							break
   180→						}
   181→					}
   182→				}
   183→			}
   184→		}
   185→	}
   186→
   187→	// For each user prompt, extract the prompt text, following assistant response, and files
   188→	for idx, userIdx := range userIndices {
   189→		// Determine the range for this prompt's conversation
   190→		endIdx := len(transcript)
   191→		if idx < len(userIndices)-1 {
   192→			endIdx = userIndices[idx+1]
   193→		}
   194→
   195→		// Extract prompt text
   196→		prompt := extractUserPromptAt(transcript, userIdx)
   197→		if prompt == "" {
   198→			continue
   199→		}
   200→
   201→		// Extract assistant responses and files from this range
   202→		slice := transcript[userIdx:endIdx]
   203→		responses := extractAssistantResponses(slice)
   204→		files := extractModifiedFiles(slice)
   205→
   206→		pairs = append(pairs, PromptResponsePair{
   207→			Prompt:    prompt,
   208→			Responses: responses,
   209→			Files:     files,
   210→		})
   211→	}
   212→
   213→	return pairs
   214→}
   215→
   216→// extractUserPromptAt extracts the user prompt at the given index.
   217→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   218→func extractUserPromptAt(transcript []transcriptLine, idx int) string {
   219→	if idx >= len(transcript) || transcript[idx].Type != transcriptTypeUser {
   220→		return ""
   221→	}
   222→
   223→	return extractUserContentFromMessage(transcript[idx].Message)
   224→}
   225→
   226→// extractUserContentFromMessage extracts user content from a raw message.
   227→// Handles both string and array content formats.
   228→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   229→// Returns empty string if the message cannot be parsed or contains no text.
   230→func extractUserContentFromMessage(message json.RawMessage) string {
   231→	var msg userMessage
   232→	if err := json.Unmarshal(message, &msg); err != nil {
   233→		return ""
   234→	}
   235→
   236→	// Handle string content
   237→	if str, ok := msg.Content.(string); ok {
   238→		return textutil.StripIDEContextTags(str)
   239→	}
   240→
   241→	// Handle array content (only if it contains text blocks)
   242→	if arr, ok := msg.Content.([]interface{}); ok {
   243→		var texts []string
   244→		for _, item := range arr {
   245→			if m, ok := item.(map[string]interface{}); ok {
   246→				if m["type"] == contentTypeText {
   247→					if text, ok := m["text"].(string); ok {
   248→						texts = append(texts, text)
   249→					}
   250→				}
   251→			}
   252→		}
   253→		if len(texts) > 0 {
   254→			return textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   255→		}
   256→	}
   257→
   258→	return ""
   259→}
   260→
   261→// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
   262→// A single prompt can trigger multiple assistant responses interspersed with tool calls.
   263→func extractAssistantResponses(transcript []transcriptLine) []string {
   264→	var texts []string
   265→	for _, line := range transcript {
   266→		if line.Type == transcriptTypeAssistant {
   267→			var msg assistantMessage
   268→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   269→				continue
   270→			}
   271→
   272→			for _, block := range msg.Content {
   273→				if block.Type == contentTypeText && block.Text != "" {
   274→					texts = append(texts, block.Text)
   275→				}
   276→			}
   277→		}
   278→	}
   279→	return texts
   280→}
   281→
   282→// extractUserPrompts extracts all user messages from the transcript in order.
   283→// Only considers messages with string content (not tool results).
   284→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
   285→func extractUserPrompts(transcript []transcriptLine) []string {
   286→	var prompts []string
   287→	for i := range transcript {
   288→		if transcript[i].Type != transcriptTypeUser {
   289→			continue
   290→		}
   291→		var msg userMessage
   292→		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   293→			continue
   294→		}
   295→
   296→		// Handle string content
   297→		if str, ok := msg.Content.(string); ok {
   298→			prompts = append(prompts, textutil.StripIDEContextTags(str))
   299→			continue
   300→		}
   301→
   302→		// Handle array content (only if it contains text blocks)
   303→		if arr, ok := msg.Content.([]interface{}); ok {
   304→			var texts []string
   305→			for _, item := range arr {
   306→				if m, ok := item.(map[string]interface{}); ok {
   307→					if m["type"] == contentTypeText {
   308→						if text, ok := m["text"].(string); ok {
   309→							texts = append(texts, text)
   310→						}
   311→					}
   312→				}
   313→			}
   314→			if len(texts) > 0 {
   315→				prompts = append(prompts, textutil.StripIDEContextTags(strings.Join(texts, "\n\n")))
   316→			}
   317→		}
   318→	}
   319→	return prompts
   320→}
   321→
   322→// extractLastUserPrompt extracts the last user message from the transcript.
   323→// Only considers messages with string content (not tool results).
   324→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   325→func extractLastUserPrompt(transcript []transcriptLine) string {
   326→	prompts := extractUserPrompts(transcript)
   327→	if len(prompts) == 0 {
   328→		return ""
   329→	}
   330→	return prompts[len(prompts)-1]
   331→}
   332→
   333→// extractLastAssistantMessage extracts the last text message from the assistant
   334→func extractLastAssistantMessage(transcript []transcriptLine) string {
   335→	for i := len(transcript) - 1; i >= 0; i-- {
   336→		if transcript[i].Type == transcriptTypeAssistant {
   337→			var msg assistantMessage
   338→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   339→				continue
   340→			}
   341→
   342→			for _, block := range msg.Content {
   343→				if block.Type == contentTypeText && block.Text != "" {
   344→					return block.Text
   345→				}
   346→			}
   347→		}
   348→	}
   349→	return ""
   350→}
   351→
   352→// findLastUserUUID finds the UUID of the last user message (that has string content)
   353→func findLastUserUUID(transcript []transcriptLine) string {
   354→	for i := len(transcript) - 1; i >= 0; i-- {
   355→		if transcript[i].Type == transcriptTypeUser {
   356→			var msg userMessage
   357→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   358→				continue
   359→			}
   360→			// Only count messages with string content (not tool results)
   361→			if _, ok := msg.Content.(string); ok {
   362→				return transcript[i].UUID
   363→			}
   364→		}
   365→	}
   366→	return ""
   367→}
   368→
   369→// filterTranscriptAfterUUID returns transcript lines after the given UUID
   370→func filterTranscriptAfterUUID(transcript []transcriptLine, uuid string) []transcriptLine {
   371→	if uuid == "" {
   372→		return transcript
   373→	}
   374→
   375→	foundIndex := -1
   376→	for i, line := range transcript {
   377→		if line.UUID == uuid {
   378→			foundIndex = i
   379→			break
   380→		}
   381→	}
   382→
   383→	if foundIndex == -1 || foundIndex == len(transcript)-1 {
   384→		return transcript
   385→	}
   386→
   387→	return transcript[foundIndex+1:]
   388→}
   389→
   390→// extractModifiedFiles extracts the list of files modified by tool calls
   391→func extractModifiedFiles(transcript []transcriptLine) []string {
   392→	fileSet := make(map[string]bool)
   393→	var files []string
   394→
   395→	for _, line := range transcript {
   396→		if line.Type == transcriptTypeAssistant {
   397→			var msg assistantMessage
   398→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   399→				continue
   400→			}
   401→
   402→			for _, block := range msg.Content {
   403→				if block.Type == contentTypeToolUse {
   404→					isModifyTool := false
   405→					for _, name := range claudecode.FileModificationTools {
   406→						if block.Name == name {
   407→							isModifyTool = true
   408→							break
   409→						}
   410→					}
   411→
   412→					if isModifyTool {
   413→						var input toolInput
   414→						if err := json.Unmarshal(block.Input, &input); err != nil {
   415→							continue
   416→						}
   417→
   418→						file := input.FilePath
   419→						if file == "" {
   420→							file = input.NotebookPath
   421→						}
   422→
   423→						if file != "" && !fileSet[file] {
   424→							fileSet[file] = true
   425→							files = append(files, file)
   426→						}
   427→					}
   428→				}
   429→			}
   430→		}
   431→	}
   432→
   433→	return files
   434→}
   435→
   436→// extractKeyActions extracts key actions from the transcript for context file
   437→func extractKeyActions(transcript []transcriptLine, maxActions int) []string {
   438→	var keyActions []string
   439→
   440→	for _, line := range transcript {
   441→		if line.Type == transcriptTypeAssistant {
   442→			var msg assistantMessage
   443→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   444→				continue
   445→			}
   446→
   447→			for _, block := range msg.Content {
   448→				if block.Type == contentTypeToolUse {
   449→					var input toolInput
   450→					_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing for display purposes
   451→
   452→					detail := input.Description
   453→					if detail == "" {
   454→						detail = input.Command
   455→					}
   456→					if detail == "" {
   457→						detail = input.FilePath
   458→					}
   459→					if detail == "" {
   460→						detail = input.Pattern
   461→					}
   462→
   463→					action := "- **" + block.Name + "**: " + detail
   464→					keyActions = append(keyActions, action)
   465→					if len(keyActions) >= maxActions {
   466→						return keyActions
   467→					}
   468→				}
   469→			}
   470→		}
   471→	}
   472→
   473→	return keyActions
   474→}
   475→
   476→// AgentTranscriptPath returns the path to a subagent's transcript file.
   477→// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
   478→// as the main transcript.
   479→func AgentTranscriptPath(transcriptDir, agentID string) string {
   480→	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
   481→}
   482→
   483→// toolResultBlock represents a tool_result in a user message
   484→type toolResultBlock struct {
   485→	Type      string `json:"type"`
   486→	ToolUseID string `json:"tool_use_id"`
   487→}
   488→
   489→// userMessageWithToolResults represents a user message that may contain tool results
   490→type userMessageWithToolResults struct {
   491→	Content []toolResultBlock `json:"content"`
   492→}
   493→
   494→// FindCheckpointUUID finds the UUID of the message containing the tool_result
   495→// for the given tool_use_id. This is used to find the checkpoint point for
   496→// transcript truncation when rewinding to a task.
   497→// Returns the UUID and true if found, empty string and false otherwise.
   498→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
   499→	for _, line := range transcript {
   500→		if line.Type != transcriptTypeUser {
   501→			continue
   502→		}
   503→
   504→		var msg userMessageWithToolResults
   505→		if err := json.Unmarshal(line.Message, &msg); err != nil {
   506→			continue
   507→		}
   508→
   509→		for _, block := range msg.Content {
   510→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
   511→				return line.UUID, true
   512→			}
   513→		}
   514→	}
   515→	return "", false
   516→}
   517→
   518→// TruncateTranscriptAtUUID returns transcript lines up to and including the
   519→// line with the given UUID. If the UUID is not found or is empty, returns
   520→// the entire transcript.
   521→//
   522→//nolint:revive // Exported for testing purposes
   523→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
   524→	if uuid == "" {
   525→		return transcript
   526→	}
   527→
   528→	for i, line := range transcript {
   529→		if line.UUID == uuid {
   530→			return transcript[:i+1]
   531→		}
   532→	}
   533→
   534→	// UUID not found, return full transcript
   535→	return transcript
   536→}
   537→
   538→// writeTranscript writes transcript lines to a file in JSONL format.
   539→func writeTranscript(path string, transcript []transcriptLine) error {
   540→	file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
   541→	if err != nil {
   542→		return fmt.Errorf("failed to create file: %w", err)
   543→	}
   544→	defer func() { _ = file.Close() }()
   545→
   546→	for _, line := range transcript {
   547→		data, err := json.Marshal(line)
   548→		if err != nil {
   549→			return fmt.Errorf("failed to marshal line: %w", err)
   550→		}
   551→		if _, err := file.Write(data); err != nil {
   552→			return fmt.Errorf("failed to write line: %w", err)
   553→		}
   554→		if _, err := file.WriteString("\n"); err != nil {
   555→			return fmt.Errorf("failed to write newline: %w", err)
   556→		}
   557→	}
   558→
   559→	return nil
   560→}
   561→
   562→// TranscriptPosition contains the position information for a transcript file.
   563→type TranscriptPosition struct {
   564→	LastUUID  string // Last non-empty UUID (from user/assistant messages)
   565→	LineCount int    // Total number of lines
   566→}
   567→
   568→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
   569→// Returns empty position if file doesn't exist or is empty.
   570→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
   571→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
   572→	if path == "" {
   573→		return TranscriptPosition{}, nil
   574→	}
   575→
   576→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
   577→	if err != nil {
   578→		if os.IsNotExist(err) {
   579→			return TranscriptPosition{}, nil
   580→		}
   581→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
   582→	}
   583→	defer func() { _ = file.Close() }()
   584→
   585→	var pos TranscriptPosition
   586→	reader := bufio.NewReader(file)
   587→
   588→	for {
   589→		lineBytes, err := reader.ReadBytes('\n')
   590→		if err != nil && err != io.EOF {
   591→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
   592→		}
   593→
   594→		if len(lineBytes) == 0 {
   595→			if err == io.EOF {
   596→				break
   597→			}
   598→			continue
   599→		}
   600→
   601→		pos.LineCount++
   602→
   603→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
   604→		var line transcriptLine
   605→		if err := json.Unmarshal(lineBytes, &line); err == nil {
   606→			if line.UUID != "" {
   607→				pos.LastUUID = line.UUID
   608→			}
   609→		}
   610→
   611→		if err == io.EOF {
   612→			break
   613→		}
   614→	}
   615→
   616→	return pos, nil
   617→}
