   103→// BuildCondensedTranscriptFromBytes parses transcript bytes and extracts a condensed view.
   104→// This is a convenience function that combines parsing and condensing.
   105→func BuildCondensedTranscriptFromBytes(content []byte) ([]Entry, error) {
