   113→// parseTranscriptFromBytes parses transcript content from a byte slice.
   114→// Uses bufio.Reader to handle arbitrarily long lines.
   115→func parseTranscriptFromBytes(content []byte) ([]TranscriptLine, error) {
   116→	var lines []TranscriptLine
   117→	reader := bufio.NewReader(bytes.NewReader(content))
   118→
   119→	for {
   120→		lineBytes, err := reader.ReadBytes('\n')
   121→		if err != nil && err != io.EOF {
   122→			return nil, fmt.Errorf("failed to read transcript: %w", err)
   123→		}
   124→
   125→		// Handle empty line or EOF without content
   126→		if len(lineBytes) == 0 {
   127→			if err == io.EOF {
   128→				break
   129→			}
   130→			continue
   131→		}
   132→
   133→		var line TranscriptLine
   134→		if err := json.Unmarshal(lineBytes, &line); err == nil {
   135→			lines = append(lines, line)
   136→		}
   137→
   138→		if err == io.EOF {
   139→			break
   140→		}
   141→	}
   142→
   143→	return lines, nil
   144→}
