   146→// BuildCondensedTranscript extracts a condensed view of the transcript.
   147→// It processes user prompts, assistant responses, and tool calls into
   148→// a simplified format suitable for LLM summarisation.
   149→func BuildCondensedTranscript(transcript []TranscriptLine) []Entry {
   150→	var entries []Entry
   151→
   152→	for _, line := range transcript {
   153→		switch line.Type {
   154→		case transcriptTypeUser:
   155→			if entry := extractUserEntry(line); entry != nil {
   156→				entries = append(entries, *entry)
   157→			}
   158→		case transcriptTypeAssistant:
   159→			assistantEntries := extractAssistantEntries(line)
   160→			entries = append(entries, assistantEntries...)
   161→		}
   162→	}
   163→
   164→	return entries
   165→}
