   167→// extractUserEntry extracts a user entry from a transcript line.
   168→// Returns nil if the line doesn't contain a valid user prompt.
   169→func extractUserEntry(line TranscriptLine) *Entry {
   170→	content := extractUserContentFromMessage(line.Message)
   171→	if content == "" {
   172→		return nil
   173→	}
