   180→// extractUserContentFromMessage extracts user content from a raw message.
   181→// Handles both string and array content formats.
   182→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   183→// Returns empty string if the message cannot be parsed or contains no text.
   184→func extractUserContentFromMessage(message json.RawMessage) string {
   185→	var msg userMessage
   186→	if err := json.Unmarshal(message, &msg); err != nil {
   187→		return ""
   188→	}
   189→
   190→	// Handle string content
   191→	if str, ok := msg.Content.(string); ok {
   192→		return textutil.StripIDEContextTags(str)
   193→	}
   194→
   195→	// Handle array content (only if it contains text blocks)
   196→	if arr, ok := msg.Content.([]interface{}); ok {
   197→		var texts []string
   198→		for _, item := range arr {
   199→			if m, ok := item.(map[string]interface{}); ok {
   200→				if m["type"] == contentTypeText {
   201→					if text, ok := m["text"].(string); ok {
   202→						texts = append(texts, text)
   203→					}
   204→				}
   205→			}
   206→		}
   207→		if len(texts) > 0 {
   208→			return textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   209→		}
   210→	}
   211→
   212→	return ""
   213→}
