   215→// extractAssistantEntries extracts assistant and tool entries from a transcript line.
   216→func extractAssistantEntries(line TranscriptLine) []Entry {
   217→	var msg assistantMessage
   218→	if err := json.Unmarshal(line.Message, &msg); err != nil {
   219→		return nil
