   222→	var entries []Entry
   223→
   224→	for _, block := range msg.Content {
   225→		switch block.Type {
   226→		case contentTypeText:
   227→			if block.Text != "" {
   228→				entries = append(entries, Entry{
   229→					Type:    EntryTypeAssistant,
   230→					Content: block.Text,
   231→				})
   232→			}
   233→		case contentTypeToolUse:
   234→			var input toolInput
   235→			_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
   236→
   237→			detail := input.Description
   238→			if detail == "" {
   239→				detail = input.Command
   240→			}
