   242→				detail = input.FilePath
   243→			}
   244→			if detail == "" {
   245→				detail = input.NotebookPath
   246→			}
   247→			if detail == "" {
   248→				detail = input.Pattern
   249→			}
   250→
   251→			entries = append(entries, Entry{
   252→				Type:       EntryTypeTool,
   253→				ToolName:   block.Name,
   254→				ToolDetail: detail,
   255→			})
   256→		}
   257→	}
