   262→// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
   263→// The format is:
   264→//
   265→//	[User] user prompt here
   266→//
   267→//	[Assistant] assistant response here
   268→//
   269→//	[Tool] ToolName: description or file path
   270→func FormatCondensedTranscript(input Input) string {
   271→	var sb strings.Builder
   272→
   273→	for i, entry := range input.Transcript {
   274→		if i > 0 {
   275→			sb.WriteString("\n")
   276→		}
   277→
   278→		switch entry.Type {
   279→		case EntryTypeUser:
   280→			sb.WriteString("[User] ")
   281→			sb.WriteString(entry.Content)
   282→			sb.WriteString("\n")
   283→		case EntryTypeAssistant:
   284→			sb.WriteString("[Assistant] ")
   285→			sb.WriteString(entry.Content)
   286→			sb.WriteString("\n")
   287→		case EntryTypeTool:
   288→			sb.WriteString("[Tool] ")
   289→			sb.WriteString(entry.ToolName)
   290→			if entry.ToolDetail != "" {
   291→				sb.WriteString(": ")
   292→				sb.WriteString(entry.ToolDetail)
   293→			}
   294→			sb.WriteString("\n")
   295→		}
   296→	}
   297→
   298→	if len(input.FilesTouched) > 0 {
   299→		sb.WriteString("\n[Files Modified]\n")
   300→		for _, file := range input.FilesTouched {
   301→			fmt.Fprintf(&sb, "- %s\n", file)
   302→		}
   303→	}
   304→
   305→	return sb.String()
   306→}
