   156→// ExtractAllPromptResponses extracts all user prompt and assistant response pairs from a transcript.
   157→// Returns pairs in chronological order (oldest first).
   158→// Each pair contains the user's prompt, assistant's text response, and files modified.
   159→func ExtractAllPromptResponses(transcript []transcriptLine) []PromptResponsePair {
   160→	var pairs []PromptResponsePair
   161→
   162→	// Find all user prompts (messages with string content, not tool results)
   163→	var userIndices []int
   164→	for i, line := range transcript {
   165→		if line.Type == transcriptTypeUser {
   166→			var msg userMessage
   167→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   168→				continue
   169→			}
   170→			// Only count messages with string content (real user prompts)
   171→			if _, ok := msg.Content.(string); ok {
   172→				userIndices = append(userIndices, i)
   173→			} else if arr, ok := msg.Content.([]interface{}); ok {
   174→				// Check if array has text blocks (also a real user prompt)
   175→				for _, item := range arr {
