   282→// extractUserPrompts extracts all user messages from the transcript in order.
   283→// Only considers messages with string content (not tool results).
   284→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
   285→func extractUserPrompts(transcript []transcriptLine) []string {
   286→	var prompts []string
   287→	for i := range transcript {
   288→		if transcript[i].Type != transcriptTypeUser {
   289→			continue
   290→		}
   291→		var msg userMessage
   292→		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   293→			continue
   294→		}
   295→
   296→		// Handle string content
   297→		if str, ok := msg.Content.(string); ok {
   298→			prompts = append(prompts, textutil.StripIDEContextTags(str))
   299→			continue
   300→		}
   301→
   302→		// Handle array content (only if it contains text blocks)
   303→		if arr, ok := msg.Content.([]interface{}); ok {
   304→			var texts []string
   305→			for _, item := range arr {
   306→				if m, ok := item.(map[string]interface{}); ok {
   307→					if m["type"] == contentTypeText {
   308→						if text, ok := m["text"].(string); ok {
   309→							texts = append(texts, text)
   310→						}
   311→					}
   312→				}
   313→			}
   314→			if len(texts) > 0 {
   315→				prompts = append(prompts, textutil.StripIDEContextTags(strings.Join(texts, "\n\n")))
   316→			}
   317→		}
   318→	}
   319→	return prompts
   320→}
