   568→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
   569→// Returns empty position if file doesn't exist or is empty.
   570→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
   571→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
   572→	if path == "" {
   573→		return TranscriptPosition{}, nil
   574→	}
   575→
   576→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
   577→	if err != nil {
   578→		if os.IsNotExist(err) {
   579→			return TranscriptPosition{}, nil
   580→		}
   581→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
   582→	}
   583→	defer func() { _ = file.Close() }()
   584→
   585→	var pos TranscriptPosition
   586→	reader := bufio.NewReader(file)
   587→
   588→	for {
   589→		lineBytes, err := reader.ReadBytes('\n')
   590→		if err != nil && err != io.EOF {
   591→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
   592→		}
   593→
   594→		if len(lineBytes) == 0 {
   595→			if err == io.EOF {
   596→				break
   597→			}
   598→			continue
   599→		}
   600→
   601→		pos.LineCount++
   602→
   603→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
   604→		var line transcriptLine
   605→		if err := json.Unmarshal(lineBytes, &line); err == nil {
   606→			if line.UUID != "" {
   607→				pos.LastUUID = line.UUID
   608→			}
   609→		}
   610→
   611→		if err == io.EOF {
   612→			break
   613→		}
   614→	}
   615→
   616→	return pos, nil
   617→}
