    18→// Generator generates checkpoint summaries using an LLM.
    19→type Generator interface {
    20→	// Generate creates a summary from checkpoint data.
    21→	// Returns the generated summary or an error if generation fails.
    22→	Generate(ctx context.Context, input Input) (*checkpoint.Summary, error)
    23→}
    24→
    25→// Input contains condensed checkpoint data for summarisation.
    26→type Input struct {
    27→	// Transcript is the condensed transcript entries
    28→	Transcript []Entry
    29→
    30→	// FilesTouched are the files modified during the session
    31→	FilesTouched []string
    32→}
    33→
    34→// EntryType represents the type of a transcript entry.
    35→type EntryType string
    36→
    37→const (
    38→	// EntryTypeUser indicates a user prompt entry.
    39→	EntryTypeUser EntryType = "user"
    40→	// EntryTypeAssistant indicates an assistant response entry.
    41→	EntryTypeAssistant EntryType = "assistant"
    42→	// EntryTypeTool indicates a tool call entry.
    43→	EntryTypeTool EntryType = "tool"
    44→)
    45→
    46→// Entry represents one item in the condensed transcript.
    47→type Entry struct {
    48→	// Type is the entry type (user, assistant, tool)
    49→	Type EntryType
    50→
    51→	// Content is the text content for user/assistant entries
    52→	Content string
    53→
    54→	// ToolName is the name of the tool (for tool entries)
    55→	ToolName string
    56→
    57→	// ToolDetail is a description or file path (for tool entries)
    58→	ToolDetail string
    59→}
    60→
    61→// TranscriptLine is an alias to the shared transcript.Line type.
    62→type TranscriptLine = transcript.Line
    63→
    64→// BuildCondensedTranscriptFromBytes parses transcript bytes and extracts a condensed view.
    65→// This is a convenience function that combines parsing and condensing.
    66→func BuildCondensedTranscriptFromBytes(content []byte) ([]Entry, error) {
    67→	lines, err := parseTranscriptFromBytes(content)
    68→	if err != nil {
    69→		return nil, err
    70→	}
    71→	return BuildCondensedTranscript(lines), nil
    72→}
    73→
    74→// parseTranscriptFromBytes parses transcript content from a byte slice.
    75→// Uses bufio.Reader to handle arbitrarily long lines.
    76→func parseTranscriptFromBytes(content []byte) ([]TranscriptLine, error) {
    77→	var lines []TranscriptLine
    78→	reader := bufio.NewReader(bytes.NewReader(content))
    79→
    80→	for {
    81→		lineBytes, err := reader.ReadBytes('\n')
    82→		if err != nil && err != io.EOF {
    83→			return nil, fmt.Errorf("failed to read transcript: %w", err)
    84→		}
    85→
    86→		// Handle empty line or EOF without content
    87→		if len(lineBytes) == 0 {
    88→			if err == io.EOF {
    89→				break
    90→			}
    91→			continue
    92→		}
    93→
    94→		var line TranscriptLine
    95→		if err := json.Unmarshal(lineBytes, &line); err == nil {
    96→			lines = append(lines, line)
    97→		}
    98→
    99→		if err == io.EOF {
   100→			break
   101→		}
   102→	}
   103→
   104→	return lines, nil
   105→}
   106→
   107→// BuildCondensedTranscript extracts a condensed view of the transcript.
   108→// It processes user prompts, assistant responses, and tool calls into
   109→// a simplified format suitable for LLM summarisation.
   110→func BuildCondensedTranscript(transcript []TranscriptLine) []Entry {
   111→	var entries []Entry
   112→
   113→	for _, line := range transcript {
   114→		switch line.Type {
   115→		case transcriptTypeUser:
   116→			if entry := extractUserEntry(line); entry != nil {
   117→				entries = append(entries, *entry)
   118→			}
   119→		case transcriptTypeAssistant:
   120→			assistantEntries := extractAssistantEntries(line)
   121→			entries = append(entries, assistantEntries...)
   122→		}
   123→	}
   124→
   125→	return entries
   126→}
   127→
   128→// extractUserEntry extracts a user entry from a transcript line.
   129→// Returns nil if the line doesn't contain a valid user prompt.
   130→func extractUserEntry(line TranscriptLine) *Entry {
   131→	content := extractUserContentFromMessage(line.Message)
   132→	if content == "" {
   133→		return nil
   134→	}
   135→	return &Entry{
   136→		Type:    EntryTypeUser,
   137→		Content: content,
   138→	}
   139→}
   140→
   141→// extractUserContentFromMessage extracts user content from a raw message.
   142→// Handles both string and array content formats.
   143→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   144→// Returns empty string if the message cannot be parsed or contains no text.
   145→func extractUserContentFromMessage(message json.RawMessage) string {
   146→	var msg userMessage
   147→	if err := json.Unmarshal(message, &msg); err != nil {
   148→		return ""
   149→	}
   150→
   151→	// Handle string content
   152→	if str, ok := msg.Content.(string); ok {
   153→		return textutil.StripIDEContextTags(str)
   154→	}
   155→
   156→	// Handle array content (only if it contains text blocks)
   157→	if arr, ok := msg.Content.([]interface{}); ok {
   158→		var texts []string
   159→		for _, item := range arr {
   160→			if m, ok := item.(map[string]interface{}); ok {
   161→				if m["type"] == contentTypeText {
   162→					if text, ok := m["text"].(string); ok {
   163→						texts = append(texts, text)
   164→					}
   165→				}
   166→			}
   167→		}
   168→		if len(texts) > 0 {
   169→			return textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   170→		}
   171→	}
   172→
   173→	return ""
   174→}
   175→
   176→// extractAssistantEntries extracts assistant and tool entries from a transcript line.
   177→func extractAssistantEntries(line TranscriptLine) []Entry {
   178→	var msg assistantMessage
   179→	if err := json.Unmarshal(line.Message, &msg); err != nil {
   180→		return nil
   181→	}
   182→
   183→	var entries []Entry
   184→
   185→	for _, block := range msg.Content {
   186→		switch block.Type {
   187→		case contentTypeText:
   188→			if block.Text != "" {
   189→				entries = append(entries, Entry{
   190→					Type:    EntryTypeAssistant,
   191→					Content: block.Text,
   192→				})
   193→			}
   194→		case contentTypeToolUse:
   195→			var input toolInput
   196→			_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
   197→
   198→			detail := input.Description
   199→			if detail == "" {
   200→				detail = input.Command
   201→			}
   202→			if detail == "" {
   203→				detail = input.FilePath
   204→			}
   205→			if detail == "" {
   206→				detail = input.NotebookPath
   207→			}
   208→			if detail == "" {
   209→				detail = input.Pattern
   210→			}
   211→
   212→			entries = append(entries, Entry{
   213→				Type:       EntryTypeTool,
   214→				ToolName:   block.Name,
   215→				ToolDetail: detail,
   216→			})
   217→		}
   218→	}
   219→
   220→	return entries
   221→}
   222→
   223→// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
   224→// The format is:
   225→//
   226→//	[User] user prompt here
   227→//
   228→//	[Assistant] assistant response here
   229→//
   230→//	[Tool] ToolName: description or file path
   231→func FormatCondensedTranscript(input Input) string {
   232→	var sb strings.Builder
   233→
   234→	for i, entry := range input.Transcript {
   235→		if i > 0 {
   236→			sb.WriteString("\n")
   237→		}
   238→
   239→		switch entry.Type {
   240→		case EntryTypeUser:
   241→			sb.WriteString("[User] ")
   242→			sb.WriteString(entry.Content)
   243→			sb.WriteString("\n")
   244→		case EntryTypeAssistant:
   245→			sb.WriteString("[Assistant] ")
   246→			sb.WriteString(entry.Content)
   247→			sb.WriteString("\n")
   248→		case EntryTypeTool:
   249→			sb.WriteString("[Tool] ")
   250→			sb.WriteString(entry.ToolName)
   251→			if entry.ToolDetail != "" {
   252→				sb.WriteString(": ")
   253→				sb.WriteString(entry.ToolDetail)
   254→			}
   255→			sb.WriteString("\n")
   256→		}
   257→	}
   258→
   259→	if len(input.FilesTouched) > 0 {
   260→		sb.WriteString("\n[Files Modified]\n")
   261→		for _, file := range input.FilesTouched {
   262→			fmt.Fprintf(&sb, "- %s\n", file)
   263→		}
   264→	}
   265→
   266→	return sb.String()
   267→}
