   550→// TestCalculateTotalTokenUsage_PerCheckpoint verifies token usage
   551→// is calculated per-checkpoint, not from the full conversation.
   552→// This tests the core CalculateTotalTokenUsage function which should:
   553→// - From line 0: count all turns
   554→// - From line N: count only turns from line N onwards
   555→func TestCalculateTotalTokenUsage_PerCheckpoint(t *testing.T) {
   556→	t.Parallel()
   557→
   558→	tmpDir := t.TempDir()
   559→	transcriptPath := tmpDir + "/transcript.jsonl"
   560→
   561→	// Build transcript with 3 turns:
   562→	// Turn 1: user + assistant (100 input, 50 output)
   563→	// Turn 2: user + assistant (200 input, 100 output)
   564→	// Turn 3: user + assistant (300 input, 150 output)
   565→	//
   566→	// Lines:
   567→	// 0: user message 1
   568→	// 1: assistant response 1 (100/50 tokens)
   569→	// 2: user message 2
   570→	// 3: assistant response 2 (200/100 tokens)
   571→	// 4: user message 3
   572→	// 5: assistant response 3 (300/150 tokens)
   573→
   574→	transcriptContent := []byte(
   575→		`{"type":"user","uuid":"u1","message":{"content":"first prompt"}}` + "\n" +
   576→			`{"type":"assistant","uuid":"a1","message":{"id":"m1","usage":{"input_tokens":100,"output_tokens":50}}}` + "\n" +
   577→			`{"type":"user","uuid":"u2","message":{"content":"second prompt"}}` + "\n" +
   578→			`{"type":"assistant","uuid":"a2","message":{"id":"m2","usage":{"input_tokens":200,"output_tokens":100}}}` + "\n" +
   579→			`{"type":"user","uuid":"u3","message":{"content":"third prompt"}}` + "\n" +
   580→			`{"type":"assistant","uuid":"a3","message":{"id":"m3","usage":{"input_tokens":300,"output_tokens":150}}}` + "\n",
   581→	)
   582→	if err := os.WriteFile(transcriptPath, transcriptContent, 0o600); err != nil {
   583→		t.Fatalf("failed to write transcript: %v", err)
   584→	}
   585→
   586→	// Test 1: From line 0 - all 3 turns = 600 input, 300 output
   587→	usage1, err := CalculateTotalTokenUsage(transcriptPath, 0, "")
   588→	if err != nil {
   589→		t.Fatalf("CalculateTotalTokenUsage(0) error: %v", err)
   590→	}
   591→	if usage1.InputTokens != 600 || usage1.OutputTokens != 300 {
   592→		t.Errorf("From line 0: got input=%d output=%d, want input=600 output=300",
   593→			usage1.InputTokens, usage1.OutputTokens)
   594→	}
