   107→// BuildCondensedTranscript extracts a condensed view of the transcript.
   108→// It processes user prompts, assistant responses, and tool calls into
   109→// a simplified format suitable for LLM summarisation.
   110→func BuildCondensedTranscript(lines []TranscriptLine) []Entry {
   111→	var entries []Entry
   112→
   113→	for _, line := range lines {
   114→		switch line.Type {
   115→		case transcript.TypeUser:
   116→			if entry := extractUserEntry(line); entry != nil {
