   141→// extractUserContentFromMessage extracts user content from a raw message.
   142→// Handles both string and array content formats.
   143→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   144→// Returns empty string if the message cannot be parsed or contains no text.
   145→func extractUserContentFromMessage(message json.RawMessage) string {
   146→	var msg transcript.UserMessage
   147→	if err := json.Unmarshal(message, &msg); err != nil {
   148→		return ""
   149→	}
   150→
   151→	// Handle string content
   152→	if str, ok := msg.Content.(string); ok {
   153→		return textutil.StripIDEContextTags(str)
   154→	}
   155→
   156→	// Handle array content (only if it contains text blocks)
   157→	if arr, ok := msg.Content.([]interface{}); ok {
   158→		var texts []string
   159→		for _, item := range arr {
   160→			if m, ok := item.(map[string]interface{}); ok {
   161→				if m["type"] == transcript.ContentTypeText {
   162→					if text, ok := m["text"].(string); ok {
   163→						texts = append(texts, text)
   164→					}
   165→				}
   166→			}
   167→		}
   168→		if len(texts) > 0 {
   169→			return textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   170→		}
   171→	}
   172→
   173→	return ""
   174→}
   175→
   176→// extractAssistantEntries extracts assistant and tool entries from a transcript line.
   177→func extractAssistantEntries(line TranscriptLine) []Entry {
   178→	var msg transcript.AssistantMessage
   179→	if err := json.Unmarshal(line.Message, &msg); err != nil {
   180→		return nil
   181→	}
   182→
   183→	var entries []Entry
   184→
   185→	for _, block := range msg.Content {
   186→		switch block.Type {
   187→		case transcript.ContentTypeText:
   188→			if block.Text != "" {
   189→				entries = append(entries, Entry{
   190→					Type:    EntryTypeAssistant,
   191→					Content: block.Text,
   192→				})
   193→			}
   194→		case transcript.ContentTypeToolUse:
   195→			var input transcript.ToolInput
   196→			_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing
   197→
   198→			detail := input.Description
   199→			if detail == "" {
   200→				detail = input.Command
   201→			}
   202→			if detail == "" {
   203→				detail = input.FilePath
   204→			}
   205→			if detail == "" {
   206→				detail = input.NotebookPath
   207→			}
   208→			if detail == "" {
   209→				detail = input.Pattern
   210→			}
   211→
   212→			entries = append(entries, Entry{
   213→				Type:       EntryTypeTool,
   214→				ToolName:   block.Name,
   215→				ToolDetail: detail,
   216→			})
   217→		}
   218→	}
   219→
   220→	return entries
   221→}
   222→
   223→// FormatCondensedTranscript formats an Input into a human-readable string for LLM.
   224→// The format is:
   225→//
   226→//	[User] user prompt here
   227→//
   228→//	[Assistant] assistant response here
   229→//
   230→//	[Tool] ToolName: description or file path
   231→func FormatCondensedTranscript(input Input) string {
   232→	var sb strings.Builder
   233→
   234→	for i, entry := range input.Transcript {
   235→		if i > 0 {
   236→			sb.WriteString("\n")
   237→		}
   238→
   239→		switch entry.Type {
   240→		case EntryTypeUser:
   241→			sb.WriteString("[User] ")
   242→			sb.WriteString(entry.Content)
   243→			sb.WriteString("\n")
   244→		case EntryTypeAssistant:
   245→			sb.WriteString("[Assistant] ")
   246→			sb.WriteString(entry.Content)
   247→			sb.WriteString("\n")
   248→		case EntryTypeTool:
   249→			sb.WriteString("[Tool] ")
   250→			sb.WriteString(entry.ToolName)
   251→			if entry.ToolDetail != "" {
   252→				sb.WriteString(": ")
   253→				sb.WriteString(entry.ToolDetail)
   254→			}
   255→			sb.WriteString("\n")
   256→		}
   257→	}
   258→
   259→	if len(input.FilesTouched) > 0 {
   260→		sb.WriteString("\n[Files Modified]\n")
   261→		for _, file := range input.FilesTouched {
   262→			fmt.Fprintf(&sb, "- %s\n", file)
   263→		}
   264→	}
   265→
   266→	return sb.String()
   267→}
